NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Joshua'

CHAPTERS = {
    1: {
        1: 'Herran palvelijan Mooseksen kuoltua Herra puhui Joosualle, Nuunin pojalle, Mooseksen palvelijalle, sanoen:',
        2: '"Palvelijani Mooses on kuollut. Mutta nouse nyt ja mene Jordanin yli, sinä ja koko tämä kansa, siihen maahan, jonka minä annan heille, israelilaisille.',
        3: 'Jokaisen paikan, johon jalkanne astuu, annan teille, kuten olen Moosekselle puhunut.',
        4: 'Maa erämaasta ja tuolta Libanonilta aina suureen virtaan, Eufrat-virtaan, saakka, koko heettiläisten maa, ja aina Suureen mereen asti, auringonlaskuun päin, on oleva aluettanne.',
        5: 'Kukaan ei kestä edessäsi koko elinaikanasi. Niin kuin minä olin Mooseksen kanssa, olen sinunkin kanssasi. En jätä sinua enkä hylkää sinua.',
        6: 'Ole luja ja rohkea. Sillä sinä jaat tälle kansalle perinnöksi sen maan, jonka olen heidän isilleen vannonut antavani heille.',
        7: 'Ole vain luja ja aivan rohkea ja noudata tarkasti kaikessa sitä lakia, jonka palvelijani Mooses on sinulle antanut. Älä poikkea siitä oikealle äläkä vasemmalle, että menestyisit, missä kuljet.',
        8: 'Älköön tämä lain kirja poistuko suustasi, vaan tutki sitä päivät ja yöt, että noudattaisit kaikkea, mitä siihen on kirjoitettu, sillä silloin tiesi käy hyvin ja silloin menestyt.',
        9: 'Olenhan sinua käskenyt: Ole luja ja rohkea. Älä säikähdä äläkä arkaile, sillä Herra, Jumalasi, on kanssasi, missä kuljet."',
        10: 'Silloin Joosua käski kansan päämiehiä sanoen:',
        11: '"Kulkekaa leirin halki ja käskekää kansaa sanoen: \'Valmistakaa itsellenne evästä, sillä kolmen päivän kuluttua te kuljette tämän Jordanin yli mennäksenne ottamaan omaksenne maan, jonka Herra, teidän Jumalanne, antaa teidän omaksenne.\'"',
        12: 'Mutta ruubenilaisille, gaadilaisille ja toiselle puolelle Manassen sukukuntaa Joosua puhui sanoen:',
        13: '"Muistakaa sitä käskyä, jonka Herran palvelija Mooses käski teille sanoen: \' Herra, teidän Jumalanne, suo teidän päästä rauhaan ja antaa teille tämän maan.\'',
        14: 'Vaimonne, lapsenne ja karjanne jääkööt siihen maahan, jonka Mooses antoi teille Jordanin tältä puolelta. Mutta teidän itsenne, kaikkien väkevien sankarien, on lähdettävä taisteluun valmiina veljienne etunenässä ja autettava heitä,',
        15: 'kunnes Herra suo veljienne päästä rauhaan niin kuin teidänkin, ja hekin ottavat omakseen sen maan, jonka Herra, Jumalanne, heille antaa. Sitten saatte palata takaisin siihen maahan, joka on teidän omanne, ja ottaa omaksenne sen maan, jonka Herran palvelija Mooses antoi teille tältä puolelta Jordanin, päivänkoiton puolelta."',
        16: 'Niin he vastasivat Joosualle sanoen: "Kaiken, minkä olet käskenyt meille, teemme, ja mihin meidät lähetät, sinne menemme.',
        17: 'Niin kuin olemme kaikessa totelleet Moosesta, niin tottelemme sinuakin. Olkoon vain Herra, Jumalasi, kanssasi, niin kuin hän oli Mooseksen kanssa.',
        18: 'Jokainen, joka niskoittelee suusi puhetta vastaan eikä tottele sanojasi kaikessa, mitä hänelle käsket, surmattakoon. Ole vain luja ja rohkea."',
    },
    2: {
        1: 'Niin Joosua, Nuunin poika, lähetti salaa Sittimistä kaksi vakoojaa, sanoen: "Menkää, katselkaa maata ja Jerikoa." Niin he menivät ja tulivat Rahab-nimisen porton taloon ja laskeutuivat siellä levolle.',
        2: 'Mutta Jerikon kuninkaalle kerrottiin näin: "Katso, tänne on yöllä tullut miehiä israelilaisten joukosta vakoilemaan maata."',
        3: 'Silloin Jerikon kuningas lähetti sanan Rahabille: "Tuo ulos ne miehet, jotka ovat tulleet luoksesi, jotka ovat tulleet taloosi, sillä he ovat tulleet vakoilemaan koko maata."',
        4: 'Mutta nainen otti molemmat miehet, piilotti heidät ja sanoi: "Miehet kyllä tulivat luokseni, mutta en tiennyt, mistä he olivat.',
        5: 'Kun kaupungin porttia oltiin pimeän tullen sulkemassa, miehet lähtivät ulos. En tiedä, minne miehet menivät. Ajakaa nopeasti heitä takaa, että saavutatte heidät."',
        6: 'Mutta hän oli vienyt heidät katolle ja kätkenyt heidät pellavanvarsien alle, joita hän oli asetellut katolle.',
        7: 'Niin miehet ajoivat heitä takaa Jordanin tietä kahluupaikoille saakka, ja kaupungin portti suljettiin, heti kun heidän takaa-ajajansa olivat menneet.',
        8: 'Mutta ennen kuin he olivat laskeutuneet levolle, hän nousi heidän luokseen katolle ja sanoi miehille:',
        9: '"Minä tiedän, että Herra antaa teille tämän maan ja että kauhu teitä kohtaan on vallannut meidät ja että kaikki maan asukkaat menehtyvät pelkoon edessänne.',
        10: 'Sillä olemme kuulleet, kuinka Herra kuivasi Kaislameren vedet tieltänne, kun lähditte Egyptistä, ja mitä teitte niille kahdelle amorilaisten kuninkaalle tuolla puolella Jordanin, Siihonille ja Oogille, jotka vihitte tuhon omiksi.',
        11: 'Kun sen kuulimme, raukesi sydämemme, eikä kenelläkään ole enää rohkeutta asettua teitä vastaan. Sillä Herra, Jumalanne, on Jumala ylhäällä taivaassa ja alhaalla maan päällä.',
        12: 'Niin vannokaa nyt minulle Herran kautta, että niin kuin olen tehnyt teille laupeuden, tekin teette laupeuden isäni perheelle. Antakaa minulle varma merkki siitä,',
        13: 'että jätätte eloon isäni, äitini, veljeni, sisareni ja kaikki heidän omaisensa ja pelastatte meidät kuolemasta."',
        14: 'Niin miehet sanoivat hänelle: "Me vastaamme hengellämme hengestänne, kunhan vain ette ilmaise tätä meidän asiaamme. Kun Herra antaa meille tämän maan, niin osoitamme sinulle laupeutta ja uskollisuutta."',
        15: 'Hän laski heidät köydellä alas ikkunasta, sillä hänen talonsa oli kiinni kaupungin muurissa, niin että hän asui muurissa kiinni.',
        16: 'Hän sanoi heille: "Menkää vuoristoon, etteivät takaa-ajajat kohtaisi teitä, ja olkaa siellä piilossa kolme päivää, kunnes takaa-ajajat ovat palanneet. Sitten voitte lähteä matkaanne."',
        17: 'Niin miehet sanoivat hänelle: "Me olemme vapaat siitä valasta, jonka meillä vannotit,',
        18: 'jollet sinä, kun tulemme tähän maahan, sido tätä punaista nauhaa siihen ikkunaan, josta laskit meidät alas, ja kokoa isääsi, äitiäsi, veljiäsi ja isäsi koko perhettä luoksesi taloon.',
        19: 'Kuka vain menee talosi ovesta ulos, sen veri tulkoon hänen oman päänsä päälle, ja me olemme vastuusta vapaat. Mutta kuka vain on kanssasi talossa, sen veri tulkoon meidän päämme päälle, jos kenen tahansa käsi sattuu häneen.',
        20: 'Mutta jos sinä ilmaiset tämän asiamme, niin me olemme vapaat valasta, jonka meillä vannotit."',
        21: 'Niin hän sanoi: "Olkoon, niin kuin sanotte", ja hän päästi heidät menemään, ja he lähtivät. Hän sitoi punaisen nauhan ikkunaan.',
        22: 'Niin he lähtivät ja tulivat vuoristoon ja viipyivät siellä kolme päivää, kunnes takaa-ajajat olivat palanneet. Takaa-ajajat etsivät heitä kaikkialta tien varrelta, mutta eivät löytäneet.',
        23: 'Sitten nuo kaksi miestä kääntyivät paluumatkalle. He laskeutuivat alas vuoristosta, menivät virran yli ja tulivat Joosuan, Nuunin pojan, luo ja kertoivat hänelle kaiken, mitä heille oli tapahtunut.',
        24: 'He sanoivat Joosualle: " Herra on antanut koko maan käsiimme, ja kaikki maan asukkaat menehtyvät pelkoon edessämme."',
    },
    3: {
        1: 'Niin Joosua nousi varhain seuraavana aamuna, ja he lähtivät liikkeelle Sittimistä ja tulivat Jordanille, hän ja kaikki israelilaiset. He olivat siellä yötä, ennen kuin menivät virran yli.',
        2: 'Mutta kolmen päivän kuluttua päällysmiehet kulkivat leirin halki',
        3: 'ja käskivät kansaa sanoen: "Kun näette Herran, Jumalanne, liitonarkin ja leeviläiset papit sitä kantamassa, niin lähtekää tekin liikkeelle paikoiltanne ja seuratkaa sitä.',
        4: 'Kuitenkin olkoon noin kahdentuhannen kyynärän välimatka teidän ja sen välillä – älkää menkö sitä lähelle – että tietäisitte tien, jota teidän on kuljettava, sillä te ette ole ennen menneet sitä tietä."',
        5: 'Joosua sanoi kansalle: "Pyhittäytykää, sillä huomenna Herra tekee ihmeellisiä tekoja teidän keskuudessanne."',
        6: 'Mutta papeille Joosua puhui sanoen: "Ottakaa liitonarkki ja kulkekaa kansan edellä." Niin he ottivat liitonarkin ja kulkivat kansan edellä.',
        7: 'Silloin Herra sanoi Joosualle: "Tästä päivästä alkaen minä teen sinut suureksi koko Israelin silmissä, jotta he tietäisivät, että niin kuin minä olin Mooseksen kanssa, niin minä olen sinunkin kanssasi.',
        8: 'Käske pappeja, jotka kantavat liitonarkkia, ja sano: \'Kun tulette Jordanin veden ääreen, niin pysähtykää Jordanin rantaan.\'"',
        9: 'Sitten Joosua sanoi israelilaisille: "Tulkaa tänne ja kuulkaa Herran, Jumalanne, sanat."',
        10: 'Joosua sanoi: "Tästä saatte tietää, että elävä Jumala on keskellänne ja karkottaa tieltänne kanaanilaiset, heettiläiset, hivviläiset, perissiläiset, girgasilaiset, amorilaiset ja jebusilaiset:',
        11: 'katso, kaiken maan Herran liitonarkki kulkee edellänne Jordanin poikki.',
        12: 'Ottakaa siis kaksitoista miestä Israelin sukukunnista, yksi mies kustakin sukukunnasta.',
        13: 'Niin pian kuin papit, jotka kantavat Herran, kaiken maan Herran, liitonarkkia, laskevat jalkansa Jordanin veteen, katkeaa Jordanin vesi, ylhäältä päin virtaava vesi, juoksussaan ja pysähtyy röykkiöksi."',
        14: 'Kun kansa sitten lähti liikkeelle teltoistaan mennäkseen Jordanin poikki, liitonarkkia kantavien pappien kulkiessa kansan edellä,',
        15: 'ja niin pian kuin liitonarkin kantajat tulivat Jordanille ja liitonarkkia kantavien pappien jalat painuivat rantaveteen, niin vaikka Jordan koko elonleikkuuajan tulvii yli kaikkien äyräidensä,',
        16: 'pysähtyi ylhäältä päin virtaava vesi ja seisoi yhtenä röykkiönä hyvin kaukana Adamin luona, sen kaupungin, joka on Saaretanin vieressä. Vesi, joka virtasi alaspäin Aromereen, Kuolleeseen mereen, hävisi kokonaan. Niin kansa kulki virran yli Jerikon kohdalta.',
        17: 'Herran liitonarkkia kantavat papit seisoivat alallaan kuivalla pohjalla keskellä Jordania, koko Israelin kulkiessa kuivaa myöten, kunnes kaikki kansa oli ehtinyt kulkea Jordanin yli.',
    },
    4: {
        1: 'Kun koko kansa oli ehtinyt kulkea Jordanin yli, Herra puhui Joosualle sanoen:',
        2: '"Ottakaa kansasta kaksitoista miestä, kustakin sukukunnasta yksi mies,',
        3: 'ja käskekää heitä sanoen: \'Ottakaa itsellenne tästä, keskeltä Jordania, siltä kohdalta, missä papit seisovat paikoillaan, kaksitoista kiveä ja viekää ne mukananne ja asettakaa ne siihen paikkaan, mihin jäätte seuraavaksi yöksi.\'"',
        4: 'Niin Joosua kutsui ne kaksitoista miestä, jotka hän oli määrännyt otettaviksi israelilaisista, yhden miehen kustakin sukukunnasta,',
        5: 'ja Joosua sanoi heille: "Menkää Herran, Jumalanne, arkin eteen keskelle Jordania, ja nostakoon kukin kiven olalleen israelilaisten sukukuntien luvun mukaan,',
        6: "että ne olisivat merkkinä teidän keskellänne. Kun lapsenne vastaisuudessa kysyvät ja sanovat: 'Mitä nämä kivet merkitsevät?'",
        7: 'niin vastatkaa heille: \'Sitä, että Jordanin vedet katkesivat Herran liitonarkin edessä. Kun se kulki Jordanin poikki, Jordanin vedet katkesivat juoksussaan. Siitä nämä kivet ovat muistona israelilaisille ikiajoiksi.\'"',
        8: 'Israelilaiset tekivät, kuten Joosua oli käskenyt, ja ottivat israelilaisten sukukuntien luvun mukaan kaksitoista kiveä keskeltä Jordania, niin kuin Herra oli puhunut Joosualle. He veivät ne mukanaan yöpymispaikkaan ja asettivat ne sinne.',
        9: 'Joosua pystytti kaksitoista [muuta] kiveä keskelle Jordania sille kohdalle, jossa liitonarkkia kantavat papit seisoivat. Siellä ne ovat vielä tänäkin päivänä.',
        10: 'Papit, jotka kantoivat arkkia, seisoivat keskellä Jordania, kunnes oli suoritettu kaikki, mitä Herra oli käskenyt Joosuan puhua kansalle, kaikki tyynni, mistä Mooses oli Joosualle käskyn antanut. Sitten kansa kulki nopeasti virran yli.',
        11: 'Kun koko kansa oli ehtinyt kulkea virran yli, menivät Herran arkki ja papit yli, kansan eteen.',
        12: 'Ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa kulkivat taisteluvalmiina israelilaisten etunenässä, niin kuin Mooses oli heille puhunut.',
        13: 'Heitä kulki noin neljäkymmentätuhantinen sotaan varustettu joukko Herran edellä taisteluun Jerikon arolle.',
        14: 'Sinä päivänä Herra teki Joosuan suureksi koko Israelin silmissä. He pelkäsivät häntä koko hänen elinaikansa, niin kuin olivat pelänneet Moosesta.',
        15: 'Herra puhui Joosualle sanoen:',
        16: '"Käske pappien, jotka kantavat lain arkkia, astua ylös Jordanista."',
        17: 'Niin Joosua käski pappeja sanoen: "Astukaa ylös Jordanista."',
        18: 'Kun nyt Herran liitonarkkia kantavat papit astuivat ylös Jordanista, niin tuskin olivat pappien jalat nousseet kuivalle maalle, kun Jordanin vesi palasi paikoilleen ja juoksi kuten ennenkin yli kaikkien äyräidensä.',
        19: 'Kansa astui ylös Jordanista ensimmäisen kuun kymmenentenä päivänä. He leiriytyivät Gilgaliin, Jerikon itäiselle rajalle.',
        20: 'Ne kaksitoista kiveä, jotka he olivat ottaneet Jordanista, Joosua pystytti Gilgaliin.',
        21: 'Hän puhui israelilaisille sanoen: "Kun lapsenne vastaisuudessa kysyvät isiltään ja sanovat: \'Mitä nämä kivet merkitsevät?\'',
        22: "niin ilmoittakaa se lapsillenne ja sanokaa: 'Israel kulki tämän Jordanin poikki kuivaa myöten,",
        23: 'koska Herra, Jumalanne, kuivasi Jordanin veden tieltänne, kunnes olitte kulkeneet virran poikki, samoin kuin Herra, Jumalanne, teki Kaislamerelle, jonka hän kuivasi tieltämme, kunnes olimme kulkeneet sen poikki.',
        24: 'Hän teki niin, jotta kaikki maan kansat tulisivat tietämään, että Herran käsi on väkevä, ja jotta te pelkäisitte Herraa, Jumalaanne, ainiaan.\'"',
    },
    5: {
        1: 'Kun kaikki amorilaisten kuninkaat, jotka asuivat Jordanin tällä puolella, lännen puolella, ja kaikki kanaanilaisten kuninkaat, jotka asuivat meren rannalla, kuulivat, kuinka Herra oli kuivannut Jordanin veden israelilaisten tieltä, kunnes he olivat kulkeneet yli, niin raukesi heidän sydämensä, eikä heillä enää ollut rohkeutta asettua israelilaisia vastaan.',
        2: 'Siihen aikaan Herra sanoi Joosualle: "Tee itsellesi kiviveitsiä ja ympärileikkaa taas israelilaiset toistamiseen."',
        3: 'Niin Joosua teki itselleen kiviveitsiä ja ympärileikkasi israelilaiset Esinahkakukkulan luona.',
        4: 'Syy siihen, että Joosua toimitti ympärileikkauksen, oli tämä: koko kansa, joka oli lähtenyt Egyptistä, miespuoliset, kaikki sotakuntoiset miehet, olivat kuolleet matkalla erämaassa heidän lähdettyään Egyptistä.',
        5: 'Sillä kaikki se kansa, joka oli lähtenyt, oli ollut ympärileikattu, mutta sitä kansaa, joka oli syntynyt matkalla erämaassa, heidän lähdettyään Egyptistä, ei ollut ympärileikattu.',
        6: 'Sillä neljäkymmentä vuotta olivat israelilaiset vaeltaneet erämaassa, kunnes oli hävinnyt koko se kansa, ne sotakuntoiset miehet, jotka olivat lähteneet Egyptistä, ne, jotka eivät olleet totelleet Herran ääntä ja joille Herra sen tähden oli vannonut, ettei hän ollut salliva heidän nähdä sitä maata, jonka Herra heidän isilleen vannotulla valalla oli luvannut antaa meille, sitä maata, joka vuotaa maitoa ja hunajaa.',
        7: 'Mutta hän herätti heidän poikansa heidän sijaansa. Ne Joosua ympärileikkasi, sillä he olivat ympärileikkaamattomia, koska heitä ei ollut ympärileikattu matkalla.',
        8: 'Kun koko kansa oli saatu ympärileikatuksi, he pysyivät paikallaan leirissä, kunnes olivat toipuneet.',
        9: 'Niin Herra sanoi Joosualle: "Tänä päivänä minä olen vierittänyt päältänne Egyptin häväistyksen." Sen tähden kutsutaan paikkaa vielä tänäkin päivänä Gilgaliksi.',
        10: 'Kun israelilaiset olivat leiriytyneet Gilgaliin, he viettivät sen kuukauden neljäntenätoista päivänä, illalla, pääsiäistä Jerikon arolla.',
        11: 'Pääsiäisen jälkeisenä päivänä he söivät sen maan tuotteista happamatonta leipää ja paahdettuja jyviä, juuri sinä päivänä.',
        12: 'Mutta seuraavana päivänä lakkasi manna, koska he söivät sen maan tuotteita, eivätkä israelilaiset enää saaneet mannaa, vaan he söivät sinä vuonna Kanaanin maan satoa.',
        13: 'Tapahtui Joosuan ollessa Jerikon luona, että hän nosti silmänsä ja näki miehen seisovan edessään, paljastettu miekka kädessä. Joosua meni hänen luokseen ja sanoi hänelle: "Oletko sinä meikäläisiä vai vihollisiamme?"',
        14: 'Niin hän sanoi: "En, vaan minä olen Herran sotajoukon Päällikkö ja olen juuri nyt tullut." Niin Joosua heittäytyi kasvoilleen maahan, kumarsi ja sanoi hänelle: "Mitä herrallani on sanottavana palvelijalleen?"',
        15: 'Herran sotajoukon Päällikkö sanoi Joosualle: "Riisu kengät jalastasi, sillä paikka, jossa seisot, on pyhä." Joosua teki niin.',
    },
    6: {
        1: 'Mutta Jeriko sulki porttinsa ja oli suljettuna israelilaisilta: ei kukaan kulkenut siitä ulos, eikä kukaan kulkenut sisälle.',
        2: 'Niin Herra sanoi Joosualle: "Katso, minä annan käsiisi Jerikon sekä sen kuninkaan ja väkevät sankarit.',
        3: 'Kulkekaa siis, kaikki sotakuntoiset miehet, kaupungin ympäri. Kiertäkää kerran kaupunki ympäri. Tee niin kuutena päivänä.',
        4: 'Seitsemän pappia kantakoon seitsemää pässinsarvista tehtyä torvea arkin edellä. Seitsemäntenä päivänä kulkekaa kaupungin ympäri seitsemän kertaa, ja papit puhaltakoot torviin.',
        5: 'Kun kuuluu pitkä pässin sarven puhallus, kun kuulette torven äänen, koko kansa nostakoon kovan sotahuudon. Silloin kaupungin muuri luhistuu siihen paikkaan, ja kansa voi rynnätä sinne ylös, kukin suoraan eteensä."',
        6: 'Silloin Joosua, Nuunin poika, kutsui papit ja sanoi heille: "Ottakaa liitonarkki, ja seitsemän pappia kantakoon seitsemää pässin sarvista tehtyä torvea Herran arkin edellä."',
        7: 'Sitten hän sanoi kansalle: "Lähtekää ja kulkekaa kaupungin ympäri. Aseväki käyköön Herran arkin edellä."',
        8: 'Tapahtui, kuten Joosua oli kansalle sanonut. Ne seitsemän pappia, jotka kantoivat niitä seitsemää pässin sarvista tehtyä torvea Herran edellä, lähtivät ja puhalsivat torviin, ja Herran liitonarkki kulki heidän jäljessään.',
        9: 'Aseväki kulki torvea puhaltavien pappien edellä, mutta muu väki kulki arkin jäljessä, samalla kun torviin puhallettiin taukoamatta.',
        10: 'Joosua käski kansaa sanoen: "Älkää nostako sotahuutoa älkääkä antako äänenne kuulua, älköönkä sanaakaan pääskö suustanne ennen kuin sinä päivänä, jona teille sanon: \'Nostakaa sotahuuto\'. Silloin se nostakaa."',
        11: 'Hän antoi Herran arkin kulkea yhden kierroksen kaupungin ympäri. Sitten he menivät leiriin ja jäivät yöksi leiriin.',
        12: 'Joosua nousi varhain seuraavana aamuna, ja papit ottivat Herran arkin.',
        13: 'Ne seitsemän pappia, jotka kantoivat seitsemää pässin sarvista tehtyä torvea Herran arkin edellä, kulkivat puhaltaen torviin taukoamatta, ja aseväki kulki heidän edellään, mutta muu väki kulki Herran arkin jäljessä samalla, kun torviin puhallettiin taukoamatta.',
        14: 'Tänä toisenakin päivänä he kulkivat kerran kaupungin ympäri ja palasivat sitten leiriin. Niin he tekivät kuutena päivänä.',
        15: 'Mutta seitsemäntenä päivänä he nousivat varhain aamun sarastaessa ja kulkivat kaupungin ympäri samalla tavalla seitsemän kertaa. Ainoastaan sinä päivänä he kulkivat kaupungin ympäri seitsemän kertaa.',
        16: 'Kun papit seitsemännellä kerralla puhalsivat torviin, Joosua sanoi kansalle: "Nostakaa sotahuuto, sillä Herra antaa teille kaupungin.',
        17: 'Kaupunki ja kaikki, mitä siinä on, vihittäköön tuhon omaksi Herran kunniaksi. Ainoastaan portto Rahab jääköön henkiin, hän ja kaikki, jotka ovat hänen kanssaan hänen talossaan, sillä hän piilotti tiedustelijat, jotka lähetimme.',
        18: 'Mutta karttakaa tuhon omaksi vihittyä, ettette vihi jotakin tuhon omaksi ja kuitenkin ota tuhon omaksi vihittyä ja niin tule vihkineiksi Israelin leiriä tuhon omaksi ja syökse sitä onnettomuuteen.',
        19: 'Kaikki hopea ja kulta sekä vaski- ja rautaesineet olkoot pyhitetyt Herralle. Ne tulkoot Herran aarteistoon."',
        20: 'Silloin kansa nosti sotahuudon ja torviin puhallettiin. Kun kansa kuuli torven äänen, se nosti kovan sotahuudon. Silloin muuri luhistui juuri siihen paikkaan, ja kansa ryntäsi ylös kaupunkiin, kukin suoraan eteensä. Niin he valloittivat kaupungin.',
        21: 'He vihkivät miekan terällä tuhon omaksi kaiken, mitä kaupungissa oli, miehet ja naiset, nuoret ja vanhat, vieläpä härät, lampaat ja aasit.',
        22: 'Mutta niille kahdelle miehelle, jotka olivat olleet vakoilemassa maata, Joosua sanoi: "Menkää sen porton taloon ja tuokaa nainen ja kaikki hänen omaisensa sieltä ulos, niin kuin olette hänelle vannoneet."',
        23: 'Silloin ne nuoret miehet, jotka olivat olleet vakoilemassa, menivät ja toivat ulos Rahabin sekä hänen isänsä, äitinsä, veljensä ja kaikki hänen omaisensa. He toivat ulos kaikki hänen sukulaisensa ja jättivät heidät Israelin leirin ulkopuolelle.',
        24: 'Mutta kaupungin ja kaikki, mitä siinä oli, he polttivat tulella. Ainoastaan hopean, kullan sekä vaski- ja rautaesineet he panivat Herran huoneen aarteistoon.',
        25: 'Mutta portto Rahabin sekä hänen isänsä perheen ja kaikki hänen omaisensa Joosua jätti henkiin. Hän jäi asumaan Israelin keskuuteen, aina tähän päivään asti, koska hän oli piilottanut ne tiedustelijat, jotka Joosua oli lähettänyt vakoilemaan Jerikoa.',
        26: 'Siihen aikaan Joosua vannotti tämän valan: "Kirottu olkoon Herran edessä se mies, joka nousee rakentamaan tätä Jerikon kaupunkia. Sen perustuksen laskemisesta hän menettäköön esikoisensa ja sen porttien pystyttämisestä nuorimpansa."',
        27: 'Herra oli Joosuan kanssa, ja hänen maineensa levisi kautta koko maan.',
    },
    7: {
        1: 'Mutta israelilaiset menettelivät uskottomasti anastamalla itselleen tuhon omaksi vihittyä. Aakan, Karmin poika, joka oli Sabdin poika, joka Seran poika, Juudan sukukuntaa, otti näet itselleen tuhon omaksi vihittyä. Silloin syttyi Herran viha israelilaisia kohtaan.',
        2: 'Joosua lähetti miehiä Jerikosta Aihin, joka on lähellä Beet-Aavenia, itään Beetelistä, ja puhui heille sanoen: "Menkää vakoilemaan maata." Niin miehet menivät ja vakoilivat Aita.',
        3: 'Kun he palasivat Joosuan luo, he sanoivat hänelle: "Älköön koko kansa menkö, vaan menköön Aita valloittamaan noin kaksi tai kolme tuhatta miestä. Älä vaivaa koko kansaa sinne, sillä niitä on vähän."',
        4: 'Niin sinne meni kansasta noin kolme tuhatta miestä, mutta he kääntyivät pakoon Ain miesten edestä.',
        5: 'Ain miehet löivät heitä kuoliaaksi noin kolmekymmentä kuusi miestä, ajoivat heitä takaa kaupungin portilta Sebarimiin asti ja voittivat heidät rinteessä. Silloin kansan sydän raukesi ja tuli kuin vedeksi.',
        6: 'Niin Joosua repäisi vaatteensa ja lankesi kasvoilleen maahan Herran arkin eteen ja oli siinä iltaan saakka, hän ja Israelin vanhimmat. He heittivät tomua päänsä päälle.',
        7: 'Joosua sanoi: "Voi, Herra, Herra, minkä tähden toit tämän kansan Jordanin yli antaaksesi meidät amorilaisten käsiin ja tuhotaksesi meidät? Oi, jospa olisimme päättäneet jäädä tuolle puolelle Jordanin!',
        8: 'Oi, Herra, mitä sanoisinkaan, kun Israel on kääntynyt pakoon vihollistensa edestä!',
        9: 'Kun kanaanilaiset ja kaikki muut maan asukkaat sen kuulevat, he saartavat meidät ja hävittävät nimemme maan päältä. Mitä aiot tehdä suuren nimesi puolesta?"',
        10: 'Mutta Herra sanoi Joosualle: "Nouse! Miksi makaat kasvoillasi?',
        11: 'Israel on tehnyt syntiä. He ovat rikkoneet liittoni, jonka olen heille säätänyt. He ovat ottaneet sitä, mikä oli tuhon omaksi vihittyä. He ovat varastaneet ja valehdelleet. He ovat panneet sen omien tavaroidensa joukkoon.',
        12: 'Sen tähden israelilaiset eivät voi kestää vihollistensa edessä, vaan heidän täytyy kääntyä pakoon vihollistensa edestä, sillä he itse ovat vihityt tuhon omiksi. En ole enää kanssanne, ellette hävitä keskuudestanne tuhon omaksi vihittyä.',
        13: 'Nouse, pyhitä kansa ja sano: Pyhittäytykää huomiseksi, sillä näin sanoo Herra, Israelin Jumala: Keskuudessasi, Israel, on jotakin tuhon omaksi vihittyä. Sinä et voi kestää vihollistesi edessä, ennen kuin olette poistaneet keskuudestanne tuhon omaksi vihityn.',
        14: 'Astukaa siis huomenaamuna sukukunnittain esiin. Se sukukunta, johon Herran arpa osuu, astukoon esiin suvuittain. Se suku, johon Herran arpa osuu, astukoon esiin perhekunnittain. Se perhekunta, johon Herran arpa osuu, astukoon esiin mies mieheltä.',
        15: 'Mutta se, jolta tavataan tuhon omaksi vihittyä, poltettakoon tulessa, hän ja kaikki, mitä hänellä on, sillä hän on rikkonut Herran liiton ja tehnyt häpeällisen teon Israelissa."',
        16: 'Joosua antoi varhain seuraavana aamuna Israelin astua sukukunnittain esiin, ja arpa osui Juudan sukukuntaan.',
        17: 'Silloin hän antoi Juudan sukukunnan astua esiin, ja arpa osui serahilaisten sukuun. Sitten hän antoi serahilaisten suvun astua esiin mies mieheltä, ja arpa osui Sabdiin.',
        18: 'Niin hän antoi hänen perhekuntansa astua esiin mies mieheltä, ja arpa osui Aakaniin, Karmin poikaan, joka oli Sabdin poika, joka Seran poika, Juudan sukukuntaa.',
        19: 'Silloin Joosua sanoi Aakanille: "Poikani, anna Herralle, Israelin Jumalalle, kunnia ja anna hänelle ylistys: tunnusta minulle, mitä olet tehnyt, äläkä salaa sitä minulta."',
        20: 'Niin Aakan vastasi Joosualle ja sanoi: "Minä olen todella tehnyt syntiä Herraa, Israelin Jumalaa, vastaan, sillä näin minä tein:',
        21: 'kun minä näin saaliin joukossa kauniin sinearilaisen paidan, kaksisataa sekeliä hopeaa ja kultalevyn, viidenkymmenen sekelin painoisen, niin minussa syttyi niihin himo, ja minä otin ne. Ne ovat kätkettyinä maahan keskelle telttaani, hopea alimpana."',
        22: 'Niin Joosua lähetti miehiä ottamaan selvää asiasta, ja he juoksivat telttaan. Siellä oli kätkö hänen teltassaan, hopea alimpana.',
        23: 'He ottivat ne teltasta, veivät ne Joosuan ja kaikkien israelilaisten luo ja panivat Herran eteen.',
        24: 'Joosua otti yhdessä koko Israelin kanssa Aakanin, Seran pojan, ja hopean, paidan ja kultalevyn, sekä hänen poikansa, tyttärensä, härkänsä, aasinsa, lampaansa, telttansa sekä kaikki, mitä hänellä oli, ja he veivät ne Aakorin laaksoon.',
        25: 'Joosua sanoi: "Miksi olet syössyt meidät onnettomuuteen? Herra syöksee sinut onnettomuuteen tänä päivänä." Silloin koko Israel kivitti hänet kuoliaaksi. He polttivat heidät tulessa ja kivittivät heidät.',
        26: 'He kasasivat hänen päälleen suuren kivikasan, joka vielä tänäkin päivänä on olemassa, ja niin Herra lauhtui vihansa hehkusta. Sen tähden kutsutaan sitä paikkaa vielä tänäkin päivänä Aakorin laaksoksi.',
    },
    8: {
        1: 'Sitten Herra sanoi Joosualle: "Älä pelkää äläkä arkaile. Ota mukaasi kaikki sotaväki ja lähde ja mene Aihin. Katso, minä annan sinun käsiisi Ain kuninkaan ja hänen kansansa, hänen kaupunkinsa ja maansa.',
        2: 'Tee Aille ja sen kuninkaalle, niin kuin teit Jerikolle ja sen kuninkaalle. Kuitenkin saatte ryöstää itsellenne, mitä sieltä on saatavana saalista ja karjaa. Aseta väijytys kaupungin taakse."',
        3: 'Niin Joosua sekä kaikki sotaväki lähti liikkeelle noustakseen ylös Aihin. Joosua valitsi kolmekymmentä tuhatta miestä, voimakkaita sankareita, ja lähetti heidät menemään yöllä.',
        4: 'Hän käski heitä sanoen: "Asettukaa väijyksiin kaupungin taakse, ei aivan kauas kaupungista, ja olkaa kaikki valmiina.',
        5: 'Mutta minä sekä kaikki väki, joka on kanssani, lähestymme kaupunkia. Kun he sitten tulevat ulos meitä vastaan niin kuin ensimmäiselläkin kerralla, niin käännymme pakoon heidän edestään.',
        6: "He seuraavat meitä niin kauas, että eristämme heidät kaupungista, sillä he sanovat: 'He pakenevat meitä niin kuin ensimmäiselläkin kerralla.' Kun näin pakenemme heitä,",
        7: 'silloin nouskaa te väijytyksestä ja ottakaa kaupunki haltuunne, sillä Herra, teidän Jumalanne, antaa sen käsiinne.',
        8: 'Kun olette saaneet kaupungin valtaanne, sytyttäkää kaupunki palamaan. Tehkää Herran sanan mukaan. Huomatkaa, että käsken teitä sen tekemään."',
        9: 'Sitten Joosua lähetti heidät menemään, ja he menivät ja asettuivat väijyksiin Beetelin ja Ain välille, länteen Aista. Mutta Joosua oli sen yön kansan kanssa.',
        10: 'Varhain seuraavana aamuna Joosua piti kansan katselmuksen ja lähti, hän ja Israelin vanhimmat, kansan etunenässä nousemaan Aihin.',
        11: 'Kaikki sotaväki, joka oli hänen kanssaan, nousi, lähestyi ja tuli kaupungin edustalle, ja he leiriytyivät Ain pohjoispuolelle, niin että laakso oli heidän ja Ain välillä.',
        12: 'Sitten hän otti noin viisituhatta miestä ja asetti heidät väijyksiin Beetelin ja Ain välille, kaupungista länteen.',
        13: 'Niin kansa, koko leiri, joka oli kaupungin pohjoispuolella, ja kaupungin länsipuolella oleva jälkijoukko asetettiin asemiinsa. Mutta Joosua meni sinä yönä keskelle laaksoa.',
        14: 'Kun Ain kuningas näki sen, kaupungin miehet, kuningas ja kaikki hänen väkensä, lähtivät varhain aamulla nopeasti taisteluun Israelia vastaan määrättyyn paikkaan aromaan puolelle. Hän ei näet tiennyt, että kaupungin takana oli väijytys häntä vastaan.',
        15: 'Niin Joosua ja koko Israel olivat joutuvinaan tappiolle ja pakenivat erämaahan päin.',
        16: 'Silloin kaupungin koko väki kutsuttiin ajamaan heitä takaa. He ajoivat Joosuaa takaa, ja niin heidät eristettiin kaupungista.',
        17: 'Eikä Aihin eikä Beeteliin jäänyt ainoatakaan miestä, joka ei lähtenyt Israelin perään, vaan he jättivät kaupungin avoimeksi ja ajoivat takaa Israelia.',
        18: 'Niin Herra sanoi Joosualle: "Ojenna keihäs, joka on kädessäsi, Aita kohti, sillä annan sen käsiisi." Joosua ojensi keihään, joka oli hänen kädessään, kaupunkia kohti.',
        19: 'Silloin väijyksissä oleva joukko nousi kiireesti paikaltaan ja riensi, heti kun hän ojensi kätensä, ja tunkeutui kaupunkiin, valloitti sen ja sytytti heti kaupungin palamaan.',
        20: 'Kun Ain miehet kääntyivät ja katsoivat taakseen, niin he näkivät kaupungista savun nousevan taivasta kohti, eivätkä he kyenneet pakenemaan, ei sinne eikä tänne. Väki, joka oli paennut erämaahan, kääntyi näet takaa-ajajia vastaan.',
        21: 'Kun Joosua ja koko Israel näki, että väijyksissä ollut joukko oli valloittanut kaupungin ja että kaupungista nousi savu, he palasivat takaisin ja voittivat Ain miehet.',
        22: 'Myös toiset lähtivät kaupungista heitä vastaan, joten he joutuivat israelilaisten väliin, toisten ollessa edessä, toisten takana. He voittivat heidät, päästämättä pakoon ja pelastumaan ainoaakaan heistä.',
        23: 'Mutta Ain kuninkaan he ottivat kiinni elävänä ja toivat hänet Joosuan eteen.',
        24: 'Kun Israel oli surmannut kaikki Ain asukkaat kedolla, erämaassa, jonne he olivat heitä ajaneet takaa, ja he kaikki olivat kaatuneet viimeiseen mieheen miekan terään, koko Israel palasi Aihin, ja siellä olevat tapettiin miekan terällä.',
        25: 'Niitä, jotka sinä päivänä kaatuivat, miehiä ja naisia, oli kaikkiaan kaksitoista tuhatta, kaikki Ain asukkaat.',
        26: 'Joosua ei vetänyt takaisin kättään, jossa hänellä oli keihäs ojennettuna, ennen kuin oli vihkinyt tuhon omiksi kaikki Ain asukkaat.',
        27: 'Ainoastaan karjan, ja mitä kaupungista oli saatavana saalista, Israel ryösti itselleen sen määräyksen mukaan, jonka Herra oli Joosualle antanut.',
        28: 'Joosua poltti Ain ja teki siitä ikiajoiksi rauniokummun, aution aina tähän päivään asti.',
        29: 'Mutta Ain kuninkaan hän ripusti hirteen, jossa hän riippui iltaan asti. Mutta auringon laskiessa Joosua käski ottaa hänen ruumiinsa alas hirrestä, ja he heittivät sen kaupungin portin edustalle ja kasasivat sen päälle suuren kivikasan, joka on siellä vielä tänäkin päivänä.',
        30: 'Silloin Joosua rakensi Eebalin vuorelle alttarin Herralle, Israelin Jumalalle,',
        31: 'niin kuin Herran palvelija Mooses oli käskenyt israelilaisten tehdä ja niin kuin on kirjoitettuna Mooseksen lain kirjassa: alttarin hakkaamattomista kivistä, joihin ei ollut rauta-aseella koskettu. He uhrasivat sen päällä Herralle polttouhreja ja rauhanuhreja.',
        32: 'Hän kirjoitti siellä kiviin jäljennöksen Mooseksen laista, jonka tämä oli kirjoittanut israelilaisille.',
        33: 'Koko Israel vanhimpineen, päämiehineen ja tuomareineen seisoi kummallakin puolella arkkia, [kääntyneinä] kohti leeviläisiä pappeja, jotka kantoivat Herran liitonarkkia, niin muukalaiset kuin maassa syntyneetkin, toinen puoli kääntyneenä Garissimin vuorta kohti, toinen puoli Eebalin vuorta kohti. Niin Israelin kansa ensiksi siunattiin, niin kuin Herran palvelija Mooses oli käskenyt.',
        34: 'Sitten hän luki kaikki lain sanat, siunauksen ja kirouksen, aivan niin kuin lain kirjassa on kirjoitettuna.',
        35: 'Joosua ei jättänyt lukematta mitään siitä, mitä Mooses oli käskenyt, kaiken Israelin seurakunnan läsnä ollessa, niin myös naisten, lasten ja mukana kulkevien muukalaisten läsnä ollessa.',
    },
    9: {
        1: 'Kun kaikki kuninkaat, jotka asuivat Jordanin tällä puolella, Vuoristossa, Alankomaassa ja pitkin Suuren meren koko rannikkoa Libanoniin päin, heettiläiset, amorilaiset, kanaanilaiset, perissiläiset, hivviläiset ja jebusilaiset, kuulivat, mitä oli tapahtunut,',
        2: 'he kokoontuivat yhteen sotiakseen yksimielisesti Joosuaa ja Israelia vastaan.',
        3: 'Mutta kun Gibeonin asukkaat kuulivat, mitä Joosua oli tehnyt Jerikolle ja Aille,',
        4: 'hekin menettelivät viekkaasti: he menivät ja tekeytyivät lähettiläiksi, ottivat kuluneita säkkejä aasiensa selkään sekä kuluneita, repeytyneitä ja korjattuja viinileilejä',
        5: 'ja panivat kuluneet, paikatut sandaalit jalkaansa ja kuluneet vaatteet päälleen. Kaikki heidän eväsleipänsä olivat kuivia ja murentuneita.',
        6: 'He menivät Joosuan luo Gilgalin leiriin ja sanoivat hänelle sekä Israelin miehille: "Olemme tulleet kaukaisesta maasta. Tehkää siis liitto kanssamme."',
        7: 'Mutta Israelin miehet vastasivat hivviläisille: "Kenties asutte täällä keskellämme, kuinka me tekisimme liiton teidän kanssanne?"',
        8: 'He sanoivat Joosualle: "Me olemme palvelijoitasi." Joosua sanoi heille: "Keitä te olette ja mistä tulette?"',
        9: 'He vastasivat hänelle: "Palvelijasi tulevat hyvin kaukaisesta maasta Herran, Jumalasi, nimen tähden. Sillä me olemme kuulleet hänestä kaiken, mitä hän teki Egyptissä,',
        10: 'ja kaiken, mitä hän teki niille kahdelle amorilaisten kuninkaalle, jotka asuivat tuolla puolella Jordanin, Siihonille, Hesbonin kuninkaalle, ja Oogille, Baasanin kuninkaalle, joka asui Astarotissa.',
        11: "Sen tähden vanhimpamme ja kaikki maamme asukkaat puhuivat meille sanoen: 'Ottakaa evästä mukaanne matkalle ja menkää heitä vastaan ja sanokaa heille: Me olemme teidän palvelijanne, tehkää nyt liitto kanssamme.'",
        12: 'Tämä leipämme oli vielä lämmintä, kun kotoa otimme sen evääksi lähtiessämme matkalle luoksenne, ja katso, nyt se on kuivaa ja murentunutta.',
        13: 'Nämä viinileilit, jotka uusina täytimme, ovat nyt repeytyneitä. Nämä vaatteemme ja sandaalimme ovat kovin pitkällä matkalla kuluneet."',
        14: 'Niin miehet ottivat heidän evästään, mutta eivät kysyneet Herran mieltä.',
        15: 'Niin Joosua takasi heille rauhan ja teki heidän kanssaan liiton, luvaten jättää heidät henkiin. Kansan päämiehet vannoivat heille valan.',
        16: 'Mutta kolmen päivän kuluttua, sen jälkeen kun liitto heidän kanssaan oli tehty, saatiin kuulla, että he olivat lähiseuduilta ja asuivat heidän keskellään.',
        17: 'Israelilaiset lähtivät liikkeelle ja tulivat kolmantena päivänä heidän kaupunkeihinsa. Heidän kaupunkinsa olivat Gibeon, Kefira, Beerot ja Kirjat-Jearim.',
        18: 'Mutta israelilaiset eivät surmanneet heitä, sillä kansan päämiehet olivat vannoneet heille valan Herran, Israelin Jumalan, kautta. Koko seurakunta niskoitteli päämiehiä vastaan.',
        19: 'Silloin kaikki päämiehet sanoivat koko seurakunnalle: "Me olemme vannoneet heille valan Herran, Israelin Jumalan, kautta emmekä nyt voi koskea heihin.',
        20: 'Mutta tämän me teemme heille: jätämme heidät henkiin, ettei viha kohtaisi meitä valan tähden, jonka olemme vannoneet."',
        21: 'Päämiehet sanoivat heistä: "Jääkööt henkiin, mutta tulkoon heistä puunhakkaajia ja vedenkantajia kaikelle kansalle" Niin päämiehet heitä käskivät.',
        22: 'Silloin Joosua kutsui heidät ja puhui heille sanoen: "Miksi olette pettäneet meidät ja sanoneet: \'Me asumme hyvin kaukana teistä\', vaikka asutte täällä keskellämme?',
        23: 'Sen tähden olkaa kirotut! Älköön ikinä ketään teistä päästettäkö olemasta minun Jumalani huoneen palvelijana, puunhakkaajana ja vedenkantajana."',
        24: 'He vastasivat Joosualle ja sanoivat: "Sinun palvelijoillesi oli kerrottu, että Herra, Jumalasi, oli käskenyt palvelijaansa Moosesta antamaan teille koko tämän maan ja tuhoamaan kaikki maan asukkaat teidän tieltänne. Sen tähden suuresti pelkäsimme henkeämme edessänne ja teimme tämän.',
        25: 'Mutta katso, nyt me olemme käsissäsi: tee meille, mikä mielestäsi on hyvin ja oikein."',
        26: 'Silloin hän teki heille näin: hän pelasti heidät israelilaisten käsistä, niin etteivät he heitä surmanneet.',
        27: 'Niin Joosua määräsi heidät sinä päivänä seurakunnan ja Herran alttarin puunhakkaajiksi ja vedenkantajiksi, aina tähän päivään asti, sitä paikkaa varten, jonka Herra oli valitseva.',
    },
    10: {
        1: 'Kun Adonisedek, Jerusalemin kuningas, kuuli, että Joosua oli valloittanut Ain ja vihkinyt sen tuhon omaksi, tehden Aille ja sen kuninkaalle, niin kuin oli tehnyt Jerikolle ja sen kuninkaalle, ja että Gibeonin asukkaat olivat tehneet rauhan Israelin kanssa ja jääneet heidän keskuuteensa,',
        2: 'niin he pelästyivät suuresti, sillä Gibeon oli suuri kaupunki, niin kuin jokin kuninkaankaupunki, ja suurempi kuin Ai, ja kaikki sen miehet olivat urhoollisia.',
        3: 'Adonisedek, Jerusalemin kuningas, lähetti sanan Hoohamille, Hebronin kuninkaalle, Piramille, Jarmutin kuninkaalle, Jaafialle, Laakiin kuninkaalle, ja Debirille, Eglonin kuninkaalle:',
        4: '"Tulkaa luokseni ja auttakaa minua, ja kukistakaamme Gibeon, koska se on tehnyt rauhan Joosuan ja israelilaisten kanssa."',
        5: 'Nuo viisi amorilaisten kuningasta, Jerusalemin kuningas, Hebronin kuningas, Jarmutin kuningas, Laakiin kuningas ja Eglonin kuningas, kokoontuivat ja lähtivät liikkeelle kaikkine joukkoineen. He asettuivat leiriin Gibeonin edustalle ja ryhtyivät taisteluun sitä vastaan.',
        6: 'Gibeonin miehet lähettivät sanan Joosualle Gilgalin leiriin: "Älköön kätesi vetäytykö auttamasta palvelijoitasi. Tule nopeasti luoksemme, pelasta meidät ja auta meitä, sillä kaikki vuoristossa asuvien amorilaisten kuninkaat ovat kokoontuneet meitä vastaan."',
        7: 'Niin Joosua lähti Gilgalista, hän ja kaikki sotaväki hänen kanssaan ja kaikki väkevät sankarit.',
        8: 'Silloin Herra sanoi Joosualle: "Älä pelkää heitä, sillä minä annan heidät käsiisi. Ei kukaan heistä kestä sinun edessäsi."',
        9: 'Niin Joosua yllätti heidät kuljettuaan koko yön Gilgalista.',
        10: 'Herra saattoi heidät hämminkiin israelilaisten edessä, niin että nämä tuottivat heille suuren tappion Gibeonissa ja ajoivat heitä takaa Beet-Hooronin solatietä surmaten heitä aina Asekaan ja Makkedaan asti.',
        11: 'Kun he paetessaan Israelia olivat Beet-Hooronin rinteessä, Herra heitti taivaasta heidän päälleen isoja kiviä, koko matkan Asekaan asti, niin että he kuolivat. Niitä, jotka kuolivat raekivistä, oli useampia kuin niitä, jotka israelilaiset surmasivat miekalla.',
        12: 'Silloin Joosua puhui Herralle, sinä päivänä, jona Herra antoi amorilaiset israelilaisten valtaan, ja sanoi Israelin silmien edessä: "Aurinko, seiso alallasi Gibeonissa, ja kuu Aijalonin laaksossa."',
        13: 'Niin aurinko seisoi liikkumatta, ja kuu pysyi paikallaan, kunnes kansa oli kostanut vihollisilleen. Niin on kirjoitettuna "Oikeamielisen kirjassa." Niin aurinko pysyi paikallaan keskitaivaalla päiväkauden, kiirehtimättä laskemaan.',
        14: 'Eikä ole ollut sen päivän vertaista, ei ennen eikä jälkeen, jona Herra näin kuuli ihmisen ääntä, sillä Herra soti Israelin puolesta.',
        15: 'Joosua ja koko Israel hänen kanssaan palasi Gilgalin leiriin.',
        16: 'Mutta nuo viisi kuningasta pakenivat ja piiloutuivat Makkedan luolaan.',
        17: 'Joosualle ilmoitettiin: "Ne viisi kuningasta on löydetty piiloutuneina Makkedan luolaan."',
        18: 'Joosua sanoi: "Vierittäkää isoja kiviä luolan suulle ja asettakaa sen eteen miehiä vartioimaan heitä.',
        19: 'Mutta te muut, älkää pysähtykö, vaan ajakaa takaa vihollisianne ja hakatkaa maahan heidän jälkijoukkonsa älkääkä päästäkö heitä menemään kaupunkeihinsa, sillä Herra, teidän Jumalanne, on antanut heidät käsiinne."',
        20: 'Kun sitten Joosua ja israelilaiset olivat tuottaneet heille hyvin suuren, perinpohjaisen tappion ja ne harvat, jotka olivat pelastuneet, olivat päässeet varustettuihin kaupunkeihin,',
        21: 'niin koko kansa palasi vahingoittumattomana takaisin Joosuan luo leiriin Makkedaan, eikä kukaan uskaltanut hiiskua sanaakaan israelilaisia vastaan.',
        22: 'Silloin Joosua sanoi: "Avatkaa luolan suu ja tuokaa ne viisi kuningasta eteeni luolasta."',
        23: 'He tekivät niin ja toivat hänen eteensä ne viisi kuningasta luolasta: Jerusalemin kuninkaan, Hebronin kuninkaan, Jarmutin kuninkaan, Laakiin kuninkaan ja Eglonin kuninkaan.',
        24: 'Kun he olivat noutaneet nämä kuninkaat Joosuan eteen, Joosua kutsui kaikki Israelin miehet ja sanoi sotaväen päälliköille, jotka olivat seuranneet häntä: "Astukaa esiin ja pankaa jalkanne näiden kuninkaiden niskalle." He astuivat esiin ja panivat jalkansa heidän niskalleen.',
        25: 'Joosua sanoi heille: "Älkää pelätkö älkääkä arkailko, vaan olkaa lujat ja rohkeat, sillä näin on Herra tekevä kaikille vihollisillenne, joita vastaan te joudutte sotimaan."',
        26: 'Sen jälkeen Joosua löi heidät kuoliaaksi ja ripusti heidät viiteen hirsipuuhun. He riippuivat hirressä iltaan asti.',
        27: 'Mutta auringonlaskun aikaan Joosua käski ottaa heidät alas hirrestä ja heittää luolaan, johon he olivat olleet piiloutuneina. He panivat luolan suulle isoja kiviä, jotka ovat siinä vielä tänäkin päivänä.',
        28: 'Samana päivänä Joosua valloitti Makkedan ja surmasi miekan terällä sen asukkaat ja sen kuninkaan. Hän vihki tuhon omiksi heidät ja jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan. Hän teki Makkedan kuninkaalle, niin kuin oli tehnyt Jerikon kuninkaalle.',
        29: 'Sitten Joosua ja koko Israel hänen kanssaan lähti Makkedasta Libnaan ja ryhtyi taisteluun Libnaa vastaan.',
        30: 'Herra antoi senkin ja sen kuninkaan Israelin käsiin. Joosua surmasi miekan terällä sen asukkaat, jokaisen, joka siellä oli, päästämättä sieltä pakoon ainoatakaan. Hän teki sen kuninkaalle saman, minkä oli tehnyt Jerikon kuninkaalle.',
        31: 'Sitten Joosua ja koko Israel hänen kanssaan lähti Libnasta Laakiiseen ja asettui leiriin sen edustalle ja ryhtyi taisteluun sitä vastaan.',
        32: 'Herra antoi Laakiin Israelin käsiin, niin että hän valloitti sen toisena päivänä. Hän surmasi miekan terällä sen asukkaat, jokaisen, joka siellä oli, samoin kuin oli tehnyt Libnalle.',
        33: 'Silloin Hooram, Geserin kuningas, tuli auttamaan Laakista, mutta Joosua voitti hänet ja hänen väkensä päästämättä heistä ainoatakaan pakoon.',
        34: 'Laakiista Joosua ja koko Israel hänen kanssaan lähti Egloniin, ja he asettuivat leiriin sen edustalle ja ryhtyivät taisteluun sitä vastaan.',
        35: 'He valloittivat sen samana päivänä ja surmasivat miekan terällä sen asukkaat. Hän vihki tuhon omaksi sinä päivänä jokaisen, joka siellä oli, samoin kuin oli tehnyt Laakiille.',
        36: 'Joosua ja koko Israel hänen kanssaan lähti Eglonista Hebroniin, ja he ryhtyivät taisteluun sitä vastaan.',
        37: 'He valloittivat sen ja surmasivat miekan terällä sen asukkaat ja sen kuninkaan, ja samoin kaikki sen alaiset kaupungit ja jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan, samoin kuin hän oli tehnyt Eglonille. Hän vihki tuhon omaksi sen ja jokaisen, joka siellä oli.',
        38: 'Sitten Joosua ja koko Israel hänen kanssaan kääntyi Debiriin ja ryhtyi taisteluun sitä vastaan.',
        39: 'Hän sai valtaansa sen ja sen kuninkaan sekä kaikki sen alaiset kaupungit, ja he surmasivat miekan terällä niiden asukkaat ja vihkivät tuhon omaksi jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan. Hän teki Debirille ja sen kuninkaalle saman, minkä oli tehnyt Hebronille ja minkä oli tehnyt Libnalle ja sen kuninkaalle.',
        40: 'Joosua valtasi koko maan, Vuoriston, Negevin, Alankomaan ja Rinnemaat, ja surmasi kaikki niiden kuninkaat, päästämättä pakoon ainoaakaan, ja vihki tuhon omaksi joka hengen, niin kuin Herra, Israelin Jumala, oli käskenyt.',
        41: 'Joosua valtasi heidän alueensa Kaades-Barneasta Gassaan saakka ja koko Goosenin maakunnan Gibeoniin saakka.',
        42: 'Kaikki nämä kuninkaat ja heidän maansa Joosua sai valtaansa yhdellä kerralla. Sillä Herra, Israelin Jumala, soti Israelin puolesta.',
        43: 'Sitten Joosua ja koko Israel hänen kanssaan palasi Gilgalin leiriin.',
    },
    11: {
        1: 'Kun Jaabin, Haasorin kuningas, sen kuuli, hän lähetti sanan Joobabille, Maadonin kuninkaalle, ja Simronin kuninkaalle ja Aksafin kuninkaalle',
        2: 'ja niille kuninkaille, jotka asuivat pohjoisessa, Vuoristossa, Aromaassa Kinarotista etelään päin, Alankomaassa ja Doorin kukkuloilla lännessä,',
        3: 'kanaanilaisille itään ja länteen, amorilaisille, heettiläisille, perissiläisille ja jebusilaisille vuoristoon ja hivviläisille Hermonin juurelle Mispan maahan.',
        4: 'Nämä lähtivät liikkeelle kaikkine joukkoineen. Väkeä oli niin paljon kuin hiekkaa meren rannalla ja hevosia ja sotavaunuja hyvin paljon.',
        5: 'Kaikki nämä kuninkaat liittyivät yhteen, tulivat ja leiriytyivät yhdessä Meeromin veden rannalle sotiakseen Israelia vastaan.',
        6: 'Silloin Herra sanoi Joosualle: "Älä pelkää heitä, sillä huomenna tähän aikaan minä annan heidät kaikki voitettuina Israelin valtaan. Sinä katkot heidän ratsujensa vuohisjänteet, ja heidän vaununsa sinä poltat tulessa."',
        7: 'Joosua ja kaikki sotaväki hänen kanssaan yllätti heidät Meeromin veden rannalla ja hyökkäsi heidän kimppuunsa.',
        8: 'Herra antoi heidät Israelin käsiin, niin että he voittivat heidät ja ajoivat heitä takaa aina suureen Siidoniin, Misrefot-Majimiin ja itään päin Mispan laaksoon asti. He voittivat heidät päästämättä heistä ainoatakaan pakoon.',
        9: 'Joosua teki heille, niin kuin Herra oli hänelle sanonut: heidän ratsujensa vuohisjänteet hän katkoi, ja heidän vaununsa hän poltti tulessa.',
        10: 'Sitten Joosua kääntyi takaisin ja valloitti Haasorin ja surmasi miekalla sen kuninkaan. Haasor oli näet muinoin kaikkien näiden kuningaskuntien pääkaupunki.',
        11: 'He surmasivat miekan terällä ja vihkivät tuhon omaksi jokaisen, joka siellä oli, niin ettei jäänyt jäljelle ainoatakaan henkeä. Haasorin hän poltti tulella.',
        12: 'Kaikki nämä kuninkaankaupungit ja niiden kuninkaat Joosua sai valtaansa, ja hän surmasi miekan terällä niiden asukkaat vihkien heidät tuhon omiksi, niin kuin Herran palvelija Mooses oli käskenyt.',
        13: 'Mutta kukkuloilla olevista kaupungeista Israel ei polttanut ainoatakaan, paitsi Haasorin, jonka Joosua poltti.',
        14: 'Kaiken, mitä näistä kaupungeista oli saatavana saalista, sekä karjan israelilaiset ryöstivät itselleen. Mutta kaikki ihmiset he surmasivat miekan terällä ja tuhosivat heidät jättämättä eloon ainoaakaan henkeä.',
        15: 'Niin kuin Herra oli käskenyt palvelijaansa Moosesta, niin Mooses oli käskenyt Joosuaa, ja niin Joosua teki, eikä hän jättänyt tekemättä mitään kaikesta siitä, minkä Herra oli Moosekselle käskenyt.',
        16: 'Niin Joosua valloitti koko tämän maan, Vuoriston, koko Negevin ja koko Goosenin maakunnan, Alankomaan ja Aromaan, niin myös Israelin vuoriston ja sen alankomaan –',
        17: 'maan Seiriin päin kohoavasta Sileästä vuoresta aina Baal-Gaadiin saakka, Libanonin laaksoon, Hermonin vuoren juurelle. Kaikki heidän kuninkaansa hän sai valtaansa ja löi heidät kuoliaaksi.',
        18: 'Kauan aikaa Joosua kävi sotaa kaikkia näitä kuninkaita vastaan.',
        19: 'Eikä ollut ainoaakaan kaupunkia, joka olisi tehnyt rauhan Israelin kanssa, paitsi ne hivviläiset, jotka asuivat Gibeonissa, vaan kaikki valloitettiin asevoimin.',
        20: 'Sillä Herralta tämä tuli. Hän paadutti heidän sydämensä, niin että he kävivät taisteluun Israelia vastaan, jotta heidät armotta vihittäisiin tuhon omiksi ja hävitettäisiin, kuten Herra oli Moosesta käskenyt.',
        21: 'Siihen aikaan Joosua tuli ja hävitti anakilaiset vuoristosta, Hebronista, Debiristä ja Anabista, koko Juudan vuoristosta ja koko Israelin vuoristosta. Joosua vihki heidät kaupunkeineen tuhon omiksi.',
        22: 'Israelilaisten maahan ei jäänyt anakilaisia. Ainoastaan Gassaan, Gatiin ja Asdodiin heitä jäi.',
        23: 'Näin Joosua valloitti koko maan, aivan niin kuin Herra oli Moosekselle puhunut. Joosua antoi sen perintöosaksi Israelille, heidän sukukunnilleen heidän osastojensa mukaan. Maa pääsi rauhaan sodasta.',
    },
    12: {
        1: 'Nämä olivat ne [Kanaanin] maan kuninkaat, jotka israelilaiset voittivat ja joiden maan he ottivat omakseen tuolla puolella Jordanin, päivänkoiton puolella, maan Arnon-joesta aina Hermonin vuoreen saakka ja koko itäpuolisen Aromaan:',
        2: 'Siihon, amorilaisten kuningas, joka asui Hesbonissa ja hallitsi maata Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalta, ja puolta Gileadia, Jabbok-jokeen saakka, joka on ammonilaisten rajana,',
        3: 'ja Aromaata aina Kinneretin järveen, sen itärantaan, saakka ja Aromaan mereen, Kuolleeseen mereen, sen itärantaan, saakka, Beet-Jesimotin tienoille, ja etelään päin Pisgan rinteiden juurelle saakka.',
        4: 'He ottivat omakseen Oogin, Baasanin kuninkaan, alueen, hänen, joka oli viimeisiä refalaisia ja asui Astarotissa ja Edreissä',
        5: 'ja hallitsi Hermonin vuorta, Salkaa ja koko Baasania gesurilaisten ja maakatilaisten alueeseen saakka ja toista puolta Gileadia, Hesbonin kuninkaan Siihonin alueeseen saakka.',
        6: 'Herran palvelija Mooses ja israelilaiset olivat voittaneet heidät. Herran palvelija Mooses oli antanut maan omaksi ruubenilaisille ja gaadilaisille ja toiselle puolelle Manassen sukukuntaa.',
        7: 'Nämä olivat ne maan kuninkaat, jotka Joosua ja israelilaiset voittivat Jordanin tällä puolella, sen länsipuolella, Libanonin laaksossa olevasta Baal-Gaadista aina Seiriin päin kohoavaan Sileään vuoreen saakka, ja joiden maan Joosua antoi Israelin sukukuntien omaksi, heidän osastojensa mukaan,',
        8: 'Vuoristossa, Alankomaassa, Aromaassa, Rinnemaissa, Erämaassa ja Negevissä, heettiläisten, amorilaisten, kanaanilaisten, perissiläisten, hivviläisten ja jebusilaisten maan:',
        9: 'Jerikon kuningas yksi, lähellä Beeteliä olevan Ain kuningas yksi,',
        10: 'Jerusalemin kuningas yksi, Hebronin kuningas yksi,',
        11: 'Jarmutin kuningas yksi, Laakiin kuningas yksi,',
        12: 'Eglonin kuningas yksi, Geserin kuningas yksi,',
        13: 'Debirin kuningas yksi, Gederin kuningas yksi,',
        14: 'Horman kuningas yksi, Aradin kuningas yksi,',
        15: 'Libnan kuningas yksi, Adullamin kuningas yksi,',
        16: 'Makkedan kuningas yksi, Beetelin kuningas yksi,',
        17: 'Tappuahin kuningas yksi, Heeferin kuningas yksi,',
        18: 'Afekin kuningas yksi, Lassaronin kuningas yksi,',
        19: 'Maadonin kuningas yksi, Haasorin kuningas yksi,',
        20: 'Simron-Meronin kuningas yksi, Aksafin kuningas yksi,',
        21: 'Taanakin kuningas yksi, Megiddon kuningas yksi,',
        22: 'Kedeksen kuningas yksi, Karmelin juurella olevan Jokneamin kuningas yksi,',
        23: 'Doorin kukkuloilla olevan Doorin kuningas yksi, Gilgalin seudun pakanoiden kuningas yksi,',
        24: 'Tirsan kuningas yksi. Kaikkiaan kolmekymmentä yksi kuningasta.',
    },
    13: {
        1: 'Kun Joosua oli käynyt vanhaksi ja iäkkääksi, Herra sanoi hänelle: "Sinä olet käynyt vanhaksi ja iäkkääksi, mutta vielä on hyvin paljon maata valtaamatta.',
        2: 'Tämä on se maa, mikä vielä on jäljellä: kaikki filistealaisten alueet ja koko gesurilaisten maa',
        3: 'Siihorista alkaen, joka on itään Egyptistä, aina Ekronin alueeseen asti pohjoisen suuntaan – se luetaan kanaanilaisten alueeseen – viisi filistealaista ruhtinasta, nimittäin Gassan, Asdodin, Askelonin, Gatin ja Ekronin ruhtinaat, niin myös avvilaiset',
        4: 'etelässä päin, koko kanaanilaisten maa ja Meara, joka on siidonilaisten, Afekiin saakka, amorilaisten alueeseen saakka,',
        5: 'ja gebalilaisten maa ja koko Libanon, päivänkoiton puolella, Hermonin vuoren juurella olevasta Baal-Gaadista siihen saakka, mistä mennään Hamatiin.',
        6: 'Kaikki vuoriston asukkaat Libanonista Misrefot-Majimiin saakka, kaikki siidonilaiset, minä karkotan israelilaisten tieltä. Arvo vain niiden maa Israelin kesken perintöosaksi, niin kuin olen sinua käskenyt.',
        7: 'Jaa siis tämä maa perintöosana yhdeksälle sukukunnalle ja toiselle puolelle Manassen sukukuntaa."',
        8: 'Samalla kun sen toinen puoli olivat näet myös ruubenilaiset ja gaadilaiset saaneet perintöosansa, jonka Mooses antoi heille tuolta puolelta Jordanin, idän puolelta, kuten Herran palvelija Mooses sen heille antoi,',
        9: 'maan Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalla olevasta kaupungista alkaen ja koko Meedeban ylätasangon Diiboniin saakka,',
        10: 'kaikki Siihonin, amorilaisten kuninkaan, kaupungit, hänen, joka hallitsi Hesbonissa, aina ammonilaisten alueeseen saakka,',
        11: 'Gileadin sekä gesurilaisten ja maakatilaisten alueet ja koko Hermonin vuoren ja koko Baasanin Salkaan saakka,',
        12: 'ja koko Oogin valtakunnan Baasanissa, hänen, joka hallitsi Astarotissa ja Edreissä ja oli viimeisiä refalaisia. Nämä Mooses voitti ja karkotti.',
        13: 'Mutta israelilaiset eivät karkottaneet gesurilaisia ja maakatilaisia, vaan gesurilaiset ja maakatilaiset jäivät asumaan Israelin keskuuteen aina tähän päivään asti.',
        14: 'Ainoastaan Leevin sukukunnalle hän ei antanut perintöosaa. Herran, Israelin Jumalan, uhrit ovat sen perintöosa, niin kuin hän on sille puhunut.',
        15: 'Mooses oli antanut maata ruubenilaisten sukukunnalle, heidän suvuilleen:',
        16: 'heille tuli alue Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalla olevasta kaupungista alkaen ja koko ylätasanko Meedeban luona,',
        17: 'Hesbon sekä kaikki sen alaiset kaupungit, jotka ovat ylätasangolla, Diibon, Baamot-Baal, Beet-Baal-Meon,',
        18: 'Jahas, Kedemot, Meefaat,',
        19: 'Kirjataim, Sibma, Seret-Sahar Laaksovuorella,',
        20: 'Beet-Peor ja Pisgan rinteet ja Beet-Jesimot,',
        21: 'ja kaikki ylätasangon kaupungit ja Siihonin, amorilaisten kuninkaan, koko valtakunta, hänen, joka hallitsi Hesbonissa ja jonka Mooses oli voittanut samalla kun Midianin ruhtinaat Evin, Rekemin, Suurin, Huurin ja Reban, jotka olivat Siihonin aliruhtinaita ja asuivat siinä maassa.',
        22: 'Muiden mukana, jotka olivat kaatuneet, israelilaiset olivat surmanneet miekalla myös tietäjä Bileamin, Beorin pojan.',
        23: 'Ruubenilaisten raja on Jordan, se on rajana. Tämä on ruubenilaisten, heidän sukujensa, perintöosa, kaupungit kylineen.',
        24: 'Mooses oli antanut Gaadin sukukunnalle, gaadilaisille, heidän suvuilleen, maata:',
        25: 'heidän alueekseen tuli Jaeser ja kaikki Gileadin kaupungit ja puolet ammonilaisten maata Aroeriin asti, joka on itään Rabbasta,',
        26: 'ja maa Hesbonista Raamat-Mispeen ja Betonimiin saakka, ja Mahanaimista Lidebirin alueeseen saakka;',
        27: 'ja laaksossa: Beet-Raam, Beet-Nimra, Sukkot ja Saafon, loput Siihonin, Hesbonin kuninkaan, valtakunnasta, rajana Jordan Kinneretin järven päähän saakka, Jordanin tuolla puolella, idän puolella.',
        28: 'Tämä on gaadilaisten, heidän sukujensa, perintöosa, kaupungit kylineen.',
        29: 'Mooses oli antanut toiselle puolelle Manassen sukukuntaa maata, ja se tuli toiselle puolelle Manassen sukukuntaa, heidän suvuilleen:',
        30: 'heidän alueekseen tuli Mahanaimista alkaen koko Baasan, Oogin, Baasanin kuninkaan, koko valtakunta, kaikki Jaairin leirikylät Baasanissa, kuusikymmentä kaupunkia,',
        31: 'ja puolet Gileadia sekä Astarot ja Edrei, Oogin valtakunnan pääkaupungit Baasanissa. Tämä tuli Maakirin, Manassen pojan, jälkeläisille, toiselle puolelle Maakirin jälkeläisiä, heidän suvuilleen.',
        32: 'Nämä ovat ne alueet, jotka Mooses oli jakanut perintöosiksi Mooabin arolla, Jordanin tuolla puolen, Jerikon kohdalla, idän puolella.',
        33: 'Mutta Leevin sukukunnalle Mooses ei ollut antanut perintöosaa. Herra, Israelin Jumala, on heidän perintöosansa, niin kuin hän on heille puhunut.',
    },
    14: {
        1: 'Nämä ovat ne alueet, jotka israelilaiset saivat perintöosiksi Kanaanin maassa, ne, jotka pappi Eleasar ja Joosua, Nuunin poika, ja israelilaisten sukukuntien perhekuntien päämiehet jakoivat heille',
        2: 'arvalla perintöosiksi sen käskyn mukaan, jonka Herra oli yhdeksästä ja puolesta sukukunnasta antanut Mooseksen kautta.',
        3: 'Sillä Mooses oli antanut kahdelle ja puolelle sukukunnalle perintöosat Jordanin tuolta puolen, mutta leeviläisille hän ei ollut antanut perintöosaa heidän keskeltään.',
        4: 'Sillä joosefilaisia oli kaksi sukukuntaa, Manasse ja Efraim. Leeviläisille taas ei annettu osuutta maahan, vaan ainoastaan kaupunkeja heidän asuttavikseen sekä niiden laidunmaat heidän karjaansa ja omaisuuttaan varten.',
        5: 'Niin kuin Herra oli Moosesta käskenyt, niin israelilaiset tekivät ja jakoivat maan.',
        6: 'Silloin juudalaiset astuivat Joosuan eteen Gilgalissa, ja kenissiläinen Kaaleb, Jefunnen poika, sanoi hänelle: "Sinä tunnet sanan, jonka Herra puhui Jumalan miehelle Moosekselle minusta ja sinusta Kaades-Barneassa.',
        7: 'Minä olin neljänkymmenen vuoden vanha, kun Herran palvelija Mooses lähetti minut Kaades-Barneasta vakoilemaan maata, ja minä annoin hänelle tietoja parhaan ymmärrykseni mukaan.',
        8: 'Mutta veljeni, jotka olivat käyneet siellä kanssani, saivat kansan sydämen raukeamaan, kun minä seurasin uskollisesti Herraa, Jumalaani.',
        9: "Sinä päivänä Mooses vannoi sanoen: 'Totisesti, se maa, johon sinä olet jalkasi astunut, on tuleva sinulle ja sinun lapsillesi perintöosaksi ikiaikoihin asti, koska olet uskollisesti seurannut Herraa, minun Jumalaani.'",
        10: 'Mutta nyt, katso, Herra on antanut minun elää, niin kuin hän oli sanonut, vielä neljäkymmentä viisi vuotta sen jälkeen, kun Herra puhui tämän sanan Moosekselle, Israelin vaeltaessa erämaassa. Katso, minä olen nyt kahdeksankymmenen viiden vuoden vanha',
        11: 'ja olen vielä tänä päivänä yhtä voimakas, kuin olin sinä päivänä, jona Mooses minut lähetti. Niin kuin voimani oli silloin, niin se on vielä nytkin: minä kykenen sotimaan, lähtemään ja tulemaan.',
        12: 'Anna minulle siis tämä vuoristo, josta Herra sinä päivänä puhui. Sinähän kuulit sinä päivänä, että siellä asuu anakilaisia ja että siellä on suuria, varustettuja kaupunkeja. Ehkä Herra on kanssani, ja karkotan heidät, kuten Herra on puhunut."',
        13: 'Silloin Joosua siunasi Kaalebin, Jefunnen pojan, ja antoi hänelle perintöosaksi Hebronin.',
        14: 'Hebron tuli kenissiläisen Kaalebin, Jefunnen pojan, perintöosaksi, kuten se on tänäkin päivänä, sen tähden että hän oli uskollisesti seurannut Herraa, Israelin Jumalaa.',
        15: 'Mutta Hebronin nimi oli muinoin Kirjat-Arba, Arban mukaan, joka oli mahtavin mies anakilaisten joukossa, kun maa oli päässyt sodasta rauhaan.',
    },
    15: {
        1: 'Juudan jälkeläisten sukukunta, heidän sukunsa, saivat arpaosansa etelästä Edomin rajaan ja Siinin erämaahan päin, etäisintä etelää myöten.',
        2: 'Heidän eteläinen rajansa alkaa Kuolleen meren päästä, sen eteläisimmästä pohjukasta,',
        3: 'jatkuu Skorpionisolan eteläpuolitse, kulkee Siiniin, nousee Kaades-Barnean eteläpuolitse, kulkee Hesroniin, nousee Addariin ja kääntyy Karkaan päin.',
        4: 'Se kulkee edelleen Asmoniin ja jatkuu Egyptin puroon. Sitten raja päättyy mereen. Tämä olkoon teidän eteläinen rajanne.',
        5: 'Itäisenä rajana on Kuollut meri Jordanin suuhun saakka. Pohjoinen raja alkaa siitä meren pohjukasta, jossa on Jordanin suu.',
        6: 'Sieltä raja nousee Beet-Hoglaan ja kulkee Beet-Araban pohjoispuolitse. Edelleen raja nousee Boohanin, Ruubenin pojan, kiveen.',
        7: 'Sitten raja nousee Debiriin Aakorin laaksosta ja kääntyy pohjoiseen päin Gilgalia kohti, joka on vastapäätä puron eteläpuolella olevaa Adummimin solaa. Sitten raja kulkee Een-Semeksen veteen ja päättyy Roogelin lähteeseen.',
        8: 'Edelleen raja nousee Ben-Hinnomin laaksoon, Jebusilaiskukkulan, se on Jerusalemin, eteläpuolitse. Sitten raja nousee sen vuoren laelle, joka on vastapäätä Hinnomin laaksoa, lännessä päin, Refaimin tasangon pohjoisessa laidassa.',
        9: 'Tämän vuoren laelta raja kaartuu Neftoahin veden lähteelle ja jatkuu Efronin vuoren kaupunkeihin, ja sitten raja kaartuu Baalaan, se on Kirjat-Jearimiin.',
        10: 'Baalasta raja kääntyy länteen päin Seirin vuoreen, kulkee Jearimin vuoren kukkulan, se on Kesalonin, pohjoispuolitse, laskeutuu Beet-Semekseen ja kulkee sitten Timnaan.',
        11: 'Edelleen raja jatkuu Ekronin kukkulaan, pohjoiseen päin. Sitten raja kaartuu Sikkeroniin, kulkee Baala-vuoreen ja jatkuu Jabneeliin. Sitten raja päättyy mereen.',
        12: 'Läntisenä rajana on Suuri meri. Se on rajana. Nämä ovat Juudan jälkeläisten, heidän sukukuntiensa, rajat yltympäri.',
        13: 'Mutta Kaalebille, Jefunnen pojalle, Joosua antoi, niin kuin Herra oli häntä käskenyt, osuuden Juudan jälkeläisten keskuudessa, Kirjat-Arban, anakilaisten isän Arban kaupungin, se on Hebronin.',
        14: 'Kaaleb karkotti sieltä kolme anakilaista, Anakin jälkeläiset Seesain, Ahimanin ja Talmain,',
        15: 'ja lähti sieltä Debirin asukkaita vastaan. Mutta Debirin nimi oli muinoin Kirjat-Seefer.',
        16: 'Silloin Kaaleb sanoi: "Joka voittaa ja valloittaa Kirjat-Seeferin, sille minä annan tyttäreni Aksan vaimoksi."',
        17: 'Niin Otniel, Kenaan, Kaalebin veljen, poika, valloitti sen. Niin Kaaleb antoi tälle tyttärensä Aksan vaimoksi.',
        18: 'Kun Aksa tuli, hän yllytti miestään, että tämä pyytäisi hänen isältään peltomaata. Aksa pudottautui aasin selästä maahan. Silloin Kaaleb sanoi hänelle: "Mikä sinun on?"',
        19: 'Niin hän vastasi: "Anna minulle siunaus, sillä sinä olet naittanut minut kuivaan maahan. Anna siis minulle vesilähteitä." Silloin hän antoi hänelle Ylälähteet ja Alalähteet.',
        20: 'Tämä on Juudan jälkeläisten sukukunnan, heidän sukujensa, perintöosa.',
        21: 'Juudan jälkeläisten sukukunnan etäisimmät kaupungit Edomin rajalla Negevissä ovat: Kabseel, Eeder, Jaagur,',
        22: 'Kiina, Diimona, Adada,',
        23: 'Kedes, Haasor, Jitnan,',
        24: 'Siif, Telem, Bealot,',
        25: 'Haasor-Hadatta, Kerijot-Hesron, se on Haasor,',
        26: 'Amam, Sema, Moolada,',
        27: 'Hasar-Gadda, Hesmon, Beet-Pelet,',
        28: 'Hasar-Suual, Beerseba ja Bisjotja,',
        29: 'Baala, Ijjim, Esem,',
        30: 'Eltolad, Kesil, Horma,',
        31: 'Siklag, Madmanna, Sansanna,',
        32: 'Lebaot, Silhim, Ain ja Rimmon – kaikkiaan kaksikymmentä yhdeksän kaupunkia kylineen.',
        33: 'Alankomaassa: Estaol, Sora, Asna,',
        34: 'Saanoah, Een-Gannim, Tappuah, Eenam,',
        35: 'Jarmut, Adullam, Sooko, Aseka,',
        36: 'Saaraim, Aditaim, Gedera ja Gederotaim – neljätoista kaupunkia kylineen;',
        37: 'Senan, Hadasa, Migdal-Gaad,',
        38: 'Dilan, Mispe, Jokteel,',
        39: 'Laakis, Boskat, Eglon,',
        40: 'Kabbon, Lahmas, Kitlis,',
        41: 'Gederot, Beet-Daagon, Naema ja Makkeda – kuusitoista kaupunkia kylineen;',
        42: 'Libna, Eter, Aasan,',
        43: 'Jiftah, Asna, Nesib,',
        44: 'Kegila, Aksib ja Maaresa – yhdeksän kaupunkia kylineen;',
        45: 'Ekron ja sen tytärkaupungit ja kylät;',
        46: 'koko se alue kylineen, joka on Asdodin puolella Ekronista mereen kulkevaa rajaa;',
        47: 'Asdod ja sen tytärkaupungit ja kylät; Gassa ja sen tytärkaupungit ja kylät Egyptin puroon asti. Ja Suuri meri on rajana.',
        48: 'Ja vuoristossa: Saamir, Jattir, Sooko,',
        49: 'Danna, Kirjat-Sanna, se on Debir,',
        50: 'Anab, Estemo, Aanim,',
        51: 'Goosen, Hoolon ja Giilo – yksitoista kaupunkia kylineen,',
        52: 'Arab, Duuma, Esan,',
        53: 'Jaanum, Beet-Tappuah, Afeka,',
        54: 'Humta, Kirjat-Arba, se on Hebron, ja Siior – yhdeksän kaupunkia kylineen,',
        55: 'Maaon, Karmel, Siif, Jutta,',
        56: 'Jisreel, Jokdeam ja Saanoah,',
        57: 'Kain, Gibea, Timna – kymmenen kaupunkia kylineen,',
        58: 'Halhul, Beet-Suur, Gedor,',
        59: 'Maarat, Beet-Anot ja Eltekon – kuusi kaupunkia kylineen,',
        60: 'Kirjat-Baal, se on Kirjat-Jearim, ja Rabba – kaksi kaupunkia kylineen.',
        61: 'Ja erämaassa: Beet-Araba, Middin, Sekaka,',
        62: 'Nibsan, Iir-Melah ja Een-Gedi – kuusi kaupunkia kylineen.',
        63: 'Mutta jebusilaisia, jotka asuivat Jerusalemissa, eivät Juudan jälkeläiset kyenneet karkottamaan, ja niin jebusilaiset jäivät asumaan Juudan jälkeläisten sekaan, Jerusalemiin, aina tähän päivään asti.',
    },
    16: {
        1: 'Joosefilaisille määräsi arpa rajan kulkemaan idästä Jerikon Jordanista Jerikon veteen ja sieltä erämaahan, joka kohoaa Jerikosta vuoristoon Beeteliä kohti.',
        2: 'Beetelistä raja jatkuu Luusiin ja kulkee arkilaisten alueelle, Atarotiin.',
        3: 'Sitten se laskeutuu länteen päin jafletilaisten alueelle, aina alemman Beet-Hooronin alueelle ja Geseriin asti ja päättyy mereen.',
        4: 'Joosefilaiset, Manasse ja Efraim, saivat perintöosakseen tämän:',
        5: 'Efraimilaisille, heidän suvuilleen, tuli seuraava alue: heidän perintöosansa itäinen raja kulkee Aterot-Addarista yliseen Beet-Hooroniin.',
        6: 'Sitten raja päättyy mereen. Pohjoisessa on Mikmetat rajana. Sieltä raja kääntyy itään päin Taanat-Siiloon ja menee sen itäpuolitse Janohaan.',
        7: 'Janohasta se laskeutuu Atarotiin ja Naaraan, koskettaa Jerikoa ja päättyy Jordaniin.',
        8: 'Tappuahista raja kulkee länteen päin Kaana-puroon ja päättyy mereen. Tämä on efraimilaisten sukukunnan, heidän sukujensa, perintöosa,',
        9: 'ja lisäksi ne kaupungit, jotka erotettiin efraimilaisille keskeltä manasselaisten perintöosaa, kaikki ne kaupungit kylineen.',
        10: 'Mutta he eivät karkottaneet kanaanilaisia, jotka asuivat Geserissä, ja kanaanilaiset jäivät asumaan Efraimin keskuuteen aina tähän päivään asti, mutta joutuivat työveron alaisiksi.',
    },
    17: {
        1: 'Manassen sukukunta sai sekin arpaosansa, sillä hän oli Joosefin esikoinen. Maakir, Manassen esikoinen, Gileadin isä, sai Gileadin ja Baasanin, sillä hän oli sotilas.',
        2: 'Muutkin manasselaiset saivat osuutensa, suvuittain: abieserilaiset, heelekiläiset, asrielilaiset, sekemiläiset, heeferiläiset ja semidalaiset. Nämä ovat Manassen, Joosefin pojan, miespuoliset jälkeläiset, suvuittain.',
        3: 'Mutta Selofhadilla, Heeferin pojalla, joka oli Gileadin poika, joka Maakirin poika, joka Manassen poika, ei ollut poikia, vaan ainoastaan tyttäriä. Nämä olivat hänen tyttäriensä nimet: Mahla, Nooga, Hogla, Milka ja Tirsa.',
        4: 'Nämä astuivat pappi Eleasarin ja Joosuan, Nuunin pojan, ja päämiesten eteen ja sanoivat: " Herra käski Mooseksen antaa meille perintöosan veljiemme keskuudessa." Silloin Joosua antoi heille Herran käskyn mukaisesti perintöosan heidän isänsä veljien keskuudesta.',
        5: 'Niin lankesi Manasselle kymmenen osaa lukuun ottamatta Gileadin maata ja Baasania tuolla puolella Jordanin,',
        6: 'koska Manassen tyttäret saivat perintöosan hänen poikiensa keskuudessa, mutta Gileadin maa joutui Manassen muille jälkeläisille.',
        7: 'Manassen raja kulkee Asserista Mikmetatiin, joka on Sikemin itäpuolella. Sitten raja menee oikealle Een-Tappuahin asukkaiden tienoille.',
        8: 'Tappuahin maa joutui Manasselle, mutta Tappuah, Manassen rajalla, efraimilaisille.',
        9: 'Sitten raja laskeutuu Kaana-puroon, puron eteläpuolelle. Mutta siellä, Manassen kaupunkien keskellä, olevat kaupungit joutuivat Efraimille. Sitten Manassen raja kulkee puron pohjoispuolelle ja päättyy mereen.',
        10: 'Eteläpuolella oleva maa joutui Efraimille, mutta pohjoispuolella oleva maa joutui Manasselle, ja sen rajana on meri. Pohjoisessa taas sen raja koskettaa Asseria ja idässä Isaskaria.',
        11: 'Isaskarista ja Asserista joutui Manasselle Beet-Sean ja sen tytärkaupungit, Jibleam ja sen tytärkaupungit, Een-Doorin asukkaat ja sen tytärkaupungit, Taanakin asukkaat ja sen tytärkaupungit, Megiddon asukkaat ja sen tytärkaupungit, kolme kukkulaa.',
        12: 'Mutta manasselaiset eivät kyenneet ottamaan haltuunsa näitä kaupunkeja, vaan kanaanilaisten onnistui jäädä asumaan siihen maahan.',
        13: 'Kun israelilaiset voimistuivat, he saattoivat kanaanilaiset työveron alaisiksi, mutta eivät karkottaneet heitä.',
        14: 'Joosefilaiset puhuivat Joosualle sanoen: "Miksi olet antanut minulle perintöosaksi vain yhden arvan ja yhden osan, vaikka minä olen lukuisa kansa, kun Herra on siunannut minua aina tähän asti?"',
        15: 'Joosua sanoi heille: "Jos sinä olet niin lukuisa kansa, niin mene metsäseudulle ja raivaa itsellesi maata sieltä perissiläisten ja refalaisten maasta, koska Efraimin vuoristo on sinulle liian ahdas."',
        16: 'Mutta joosefilaiset vastasivat: "Ei vuoristo riitä meille. Kaikilla kanaanilaisilla, jotka asuvat tasangoilla, on raudoitettuja sotavaunuja, sekä niillä, jotka asuvat Beet-Seanissa ja sen tytärkaupungeissa, että niillä, jotka asuvat Jisreelin tasangolla."',
        17: 'Silloin Joosua puhui Joosefin heimolle, Efraimille ja Manasselle, sanoen: "Sinä olet lukuisa kansa ja sinun voimasi on suuri. Sinua ei ole jätettävä yhdelle ainoalle arpaosalle,',
        18: 'vaan vuoristo on tuleva omaksesi. Koska se on metsäseutua, sinun on se raivattava, ja sen laitapuoletkin tulevat omiksesi. Sillä sinun on karkotettava kanaanilaiset, vaikka heillä on raudoitettuja sotavaunuja ja vaikka he ovat voimakkaita."',
    },
    18: {
        1: 'Sitten koko israelilaisten seurakunta kokoontui Siiloon, ja he pystyttivät sinne ilmestysmajan, sitten kun maa oli tullut heille alamaiseksi.',
        2: 'Mutta israelilaisista oli jäljellä vielä seitsemän sukukuntaa, joiden perintöosa oli jakamatta.',
        3: 'Joosua sanoi israelilaisille: "Kuinka kauan hidastelette ettekä mene ottamaan omaksenne maata, jonka Herra, isienne Jumala, on teille antanut?',
        4: 'Tuokaa tänne jokaisesta sukukunnasta kolme miestä, niin lähetän heidät menemään ja kiertelemään maata ja kirjaamaan sen heidän perintöosiensa [jakoa] varten. Tulkoot sitten takaisin luokseni.',
        5: 'He jakakoot maan seitsemään osaan. Juuda pysyköön alueellaan etelässä, ja Joosefin heimo pysyköön alueellaan pohjoisessa.',
        6: 'Pankaa maa, ne seitsemän osaa, kirjaan ja tuokaa kirja tänne minulle, niin minä heitän teidän puolestanne arpaa täällä Herran, Jumalamme, edessä.',
        7: 'Sillä leeviläisillä ei ole osuutta teidän keskuudessanne, vaan Herran pappeus on heidän perintöosansa. Gaad ja Ruuben ja toinen puoli Manassen sukukuntaa taas ovat saaneet tuolta puolelta Jordanin, idän puolelta, perintöosansa, jonka Herran palvelija Mooses antoi heille."',
        8: 'Miehet nousivat ja lähtivät. Joosua käski lähtevien panna kirjaan maan sanoen: "Menkää maa ristiin rastiin ja pankaa se kirjaan ja palatkaa sitten luokseni, niin heitän teidän puolestanne arpaa täällä Herran edessä Siilossa."',
        9: 'Miehet lähtivät, kulkivat kautta maan ja panivat sen kirjaan kaupunki kaupungilta, seitsemänä osana, ja tulivat takaisin Joosuan luo Siilon leiriin.',
        10: 'Sitten Joosua heitti heidän puolestaan arpaa Siilossa Herran edessä, ja Joosua jakoi siellä maan israelilaisille, heidän osastojensa mukaan.',
        11: 'Arpa nousi benjaminilaisten sukukunnalle, heidän suvuilleen. Heidän arvalla saamansa alue oli Juudan jälkeläisten ja joosefilaisten välissä.',
        12: 'Heidän pohjoinen rajansa lähtee Jordanista, ja raja nousee Jerikon pohjoispuolella olevalle kukkulalle ja nousee vuoristoon länteen päin ja päättyy Beet-Aavenin erämaahan.',
        13: 'Sieltä raja kulkee Luusiin, Luusin eteläpuolella olevalle kukkulalle, se on Beeteliin. Sitten raja laskeutuu Aterot-Addariin vuoren yli, joka on alemman Beet-Hooronin eteläpuolella.',
        14: 'Sitten raja kaartuu ja kääntyy läntisenä rajana etelään siitä vuoresta, joka on vastapäätä Beet-Hooronia, sen eteläpuolella, ja päättyy Kirjat-Baaliin, se on Kirjat-Jearimiin, Juudan jälkeläisten kaupunkiin. Tämä on läntinen raja.',
        15: 'Mutta eteläinen raja lähtee Kirjat-Jearimin laidasta lännen puolelta ja jatkuu Neftoahin veden lähteelle.',
        16: 'Sitten raja laskeutuu sen vuoren päähän, joka on vastapäätä Ben-Hinnomin laaksoa, Refaimin tasangon pohjoisessa laidassa. Sieltä se laskeutuu Hinnomin laaksoon Jebusilaiskukkulan eteläpuolitse ja edelleen Roogelin lähteelle.',
        17: 'Sitten se kaartuu pohjoiseen päin ja jatkuu Een-Semekseen ja edelleen kivikoille, jotka ovat vastapäätä Adummimin solaa, ja laskeutuu Boohanin, Ruubenin pojan, kiveen.',
        18: 'Edelleen se kulkee Aromaahan päin olevan kukkulan pohjoispuolitse ja laskeutuu Aromaalle.',
        19: 'Sitten raja kulkee Beet-Hoglan kukkulan pohjoispuolitse, ja raja päättyy Kuolleen meren pohjoiseen pohjukkaan, Jordanin eteläpäähän. Tämä on eteläinen raja.',
        20: 'Mutta idän puolella rajana on Jordan. Tämä on benjaminilaisten, heidän sukujensa, perintöosa rajoineen ympäriinsä.',
        21: 'Benjaminilaisten sukukunnan, heidän sukujensa, kaupungit ovat: Jeriko, Beet-Hogla, Eemek-Kesis,',
        22: 'Beet-Araba, Semaraim, Beetel,',
        23: 'Avvim, Paara, Ofra,',
        24: 'Kefar-Ammoni, Ofni ja Geba – kaksitoista kaupunkia kylineen;',
        25: 'Gibeon, Raama, Beerot,',
        26: 'Mispe, Kefira, Moosa,',
        27: 'Rekem, Jirpeel, Tarala,',
        28: 'Seela, Elef, Jebus, se on Jerusalem, Gibeat ja Kirjat – neljätoista kaupunkia kylineen. Tämä on benjaminilaisten, heidän sukujensa, perintöosa.',
    },
    19: {
        1: 'Toinen arpa tuli Simeonille, simeonilaisten sukukunnalle, heidän suvuilleen. Heidän perintöosansa tuli olemaan keskellä Juudan jälkeläisten perintöosaa.',
        2: 'Heidän perintöosakseen tuli: Beerseba, Seba, Moolada,',
        3: 'Hasar-Suual, Baala, Esem,',
        4: 'Eltolad, Betul, Horma,',
        5: 'Siklag, Beet-Markabot, Hasar-Suusa,',
        6: 'Beet-Lebaot ja Saaruhen – kolmetoista kaupunkia kylineen;',
        7: 'Ain, Rimmon, Eeter ja Aasan – neljä kaupunkia kylineen;',
        8: 'sitten kaikki ne kylät, jotka ovat näiden kaupunkien ympärillä, aina Baalat-Beeriin, Negevin Raamaan, saakka. Tämä on simeonilaisten sukukunnan, heidän sukujensa, perintöosa.',
        9: 'Juudan jälkeläisten osasta saivat simeonilaiset perintöosansa, sillä Juudan jälkeläisille oli heidän osuutensa liian suuri. Niin simeonilaiset saivat perintöosansa heidän perintöosansa keskeltä.',
        10: 'Kolmas arpa nousi sebulonilaisille, heidän suvuilleen, ja heidän perintöosansa alue tuli ulottumaan Saaridiin asti.',
        11: 'Lännen suuntaan heidän rajansa nousee Maralaan, koskettaa Dabbesetia ja puroa, joka on Jokneamin itäpuolella.',
        12: 'Itään, päivänkoittoon päin, kääntyy raja Saaridista Kislot-Taaborin alueelle ja jatkuu Daberatiin ja nousee Jaafiaan.',
        13: 'Sieltä se kulkee itään, päivänkoittoon päin, Gat-Heeferiin ja Eet-Kasiniin ja jatkuu Rimmoniin, joka ulottuu Neegaan.',
        14: 'Sitten raja kääntyy sen pohjoispuolitse Hannatoniin ja päättyy Jiftah-Eelin laaksoon.',
        15: 'Kattat, Nahalal, Simron, Jidala ja Beetlehem – kaksitoista kaupunkia kylineen.',
        16: 'Tämä on sebulonilaisten, heidän sukujensa, perintöosa, nämä kaupungit kylineen.',
        17: 'Neljäs arpa tuli Isaskarille, isaskarilaisille, heidän suvuilleen.',
        18: 'Heidän alueellaan tuli olemaan Jisreel, Kesullot, Suunem,',
        19: 'Hafaraim, Siion, Anaharat,',
        20: 'Rabbit, Kisjon, Ebes,',
        21: 'Remet, Een-Gannim, Een-Hadda ja Beet-Passes;',
        22: 'ja raja koskettaa Taaboria, Sahasimia, Beet-Semestä, ja heidän rajansa päättyy Jordaniin – kuusitoista kaupunkia kylineen.',
        23: 'Tämä on isaskarilaisten sukukunnan, heidän sukujensa, perintöosa, kaupungit kylineen.',
        24: 'Viides arpa tuli asserilaisten sukukunnalle, heidän suvuilleen.',
        25: 'Heidän alueellaan tulivat olemaan Helkat, Hali, Beten ja Aksaf,',
        26: 'Alammelek, Amad ja Misal. Lännessä raja koskettaa Karmelia ja Siihor-Libnatia,',
        27: 'kääntyy sitten auringonnousuun päin Beet-Daagoniin ja koskettaa Sebulonia ja Jiftah-Eelin laaksoa pohjoisessa, Beet-Eemekiä ja Negieliä ja jatkuu Kaabulin pohjoispuolitse',
        28: 'Ebroniin, Rehobiin, Hammoniin ja Kaanaan, aina suureen Siidoniin saakka.',
        29: 'Sitten raja kääntyy Raamaan ja menee Tyyron varustettuun kaupunkiin saakka. Sitten raja kääntyy Hoosaan ja päättyy mereen, Heebelistä Aksibiin.',
        30: 'Umma, Afek ja Rehob – kaksikymmentä kaksi kaupunkia kylineen.',
        31: 'Tämä on asserilaisten sukukunnan, heidän sukujensa, perintöosa, nämä kaupungit kylineen.',
        32: 'Kuudes arpa tuli naftalilaisille, naftalilaisten suvuille.',
        33: 'Heidän rajansa tuli kulkemaan Heelefistä, Saanannimin tammesta, Adami-Nekebin ja Jabneelin kautta Lakkumiin asti ja päättyy Jordaniin.',
        34: 'Raja kääntyy länteen päin Asnot-Taaboriin ja jatkuu sieltä Hukkokiin ja koskettaa etelässä Sebulonia, lännessä Asseria ja idässä Juudaa Jordanin luona.',
        35: 'Varustettuja kaupunkeja ovat: Siddim, Seer, Hammat, Rakkat, Kinneret,',
        36: 'Adama, Raama, Haasor,',
        37: 'Kedes, Edrei, Een-Haasor,',
        38: 'Jireon, Migdal-Eel, Horem, Beet-Anat ja Beet-Semes – yhdeksäntoista kaupunkia kylineen.',
        39: 'Tämä on naftalilaisten sukukunnan, heidän sukujensa, perintöosa, kaupungit kylineen.',
        40: 'Seitsemäs arpa tuli daanilaisten sukukunnalle, heidän suvuilleen.',
        41: 'Heidän perintöosansa alueella tulivat olemaan Sora, Estaol, Iir-Semes,',
        42: 'Saalabbin, Aijalon, Jitla,',
        43: 'Eelon, Timna, Ekron,',
        44: 'Elteke, Gibbeton, Baalat,',
        45: 'Jehud, Bene-Berak, Gat-Rimmon,',
        46: 'Mee-Jarkon ja Rakkon, sekä Jaafoon päin oleva alue.',
        47: 'Mutta daanilaisten alue joutui heiltä pois. Niin daanilaiset lähtivät ja taistelivat Lesemiä vastaan ja valloittivat sen ja surmasivat miekan terällä sen asukkaat ja ottivat sen omakseen ja asettuivat sinne. He antoivat Lesemille nimen Daan, isänsä Daanin mukaan.',
        48: 'Tämä on daanilaisten sukukunnan, heidän sukujensa, perintöosa, nämä kaupungit kylineen.',
        49: 'Kun israelilaiset olivat saaneet jaetuksi maan sen rajoja myöten, he antoivat Joosualle, Nuunin pojalle, perintöosan keskuudessaan.',
        50: 'Herran käskyn mukaisesti he antoivat hänelle sen kaupungin, jota hän pyysi, Timnat-Serahin Efraimin vuoristossa. Hän rakensi kaupungin uudestaan ja asettui sinne.',
        51: 'Nämä ovat ne perintöosat, jotka pappi Eleasar ja Joosua, Nuunin poika, ja israelilaisten sukukuntien perhekuntapäämiehet jakoivat arvalla Siilossa Herran edessä, ilmestysmajan ovella. He saivat tehdyksi maan jakamisen.',
    },
    20: {
        1: 'Herra puhui Joosualle sanoen:',
        2: '"Puhu israelilaisille ja sano: Määrätkää itsellenne ne turvakaupungit, joista minä olen teille Mooseksen kautta puhunut,',
        3: 'että niihin voisi paeta tappaja, joka tapaturmaisesti, tahtomattaan, on surmannut jonkun. Ne olkoot teillä turvapaikkoina verenkostajalta.',
        4: 'Kun joku pakenee johonkin näistä kaupungeista, pysähtyköön kaupungin portin ovelle ja kertokoon asiansa sen kaupungin vanhimmille. He ottakoot hänet luokseen turvaan kaupunkiin ja antakoot hänelle paikan, jossa hän saa asua heidän luonaan.',
        5: 'Jos verenkostaja ajaa häntä takaa, älkööt he luovuttako tappajaa hänen käsiinsä, koska hän tahtomattaan ja häntä ennestään vihaamatta tappoi lähimmäisensä.',
        6: 'Asukoon hän siinä kaupungissa, kunnes on ollut kansan tuomittavana, ja silloisen ylipapin kuolemaan saakka. Sitten tappaja tulkoon taas takaisin omaan kaupunkiinsa ja kotiinsa, kaupunkiin, josta oli paennut."',
        7: 'Niin he pyhittivät sitä varten Kedeksen Galileasta, Naftalin vuoristosta, Sikemin Efraimin vuoristosta ja Kirjat-Arban, se on Hebronin, Juudan vuoristosta.',
        8: 'Jerikon tuolta puolen Jordanin itäpuolelta he määräsivät Ruubenin sukukunnasta Beserin erämaasta, ylätasangolta, ja Gaadin sukukunnasta Raamotin, Gileadista, ja Manassen sukukunnasta Goolanin, Baasanista.',
        9: 'Nämä ovat ne kaupungit, jotka asetettiin kaikille israelilaisille ja heidän keskuudessaan asuville muukalaisille sitä varten, että niihin voisi paeta jokainen, joka tahattomasti oli surmannut jonkun, eikä hänen tarvitsisi kuolla verenkostajan käden kautta, ennen kuin oli ollut kansan tuomittavana.',
    },
    21: {
        1: 'Leeviläisten perhekuntien päämiehet astuivat pappi Eleasarin ja Joosuan, Nuunin pojan, eteen ja israelilaisten sukukuntien perhekuntien päämiesten eteen',
        2: 'ja puhuivat heille Siilossa Kanaanin maassa, sanoen: " Herra käski Mooseksen kautta antaa meille kaupunkeja asuaksemme ja niiden laidunmaat karjaamme varten."',
        3: 'Niin israelilaiset antoivat leeviläisille perintöosastaan Herran käskyn mukaan nämä kaupungit laidunmaineen:',
        4: 'Arpa tuli kehatilaisten suvuille niin, että leeviläisistä pappi Aaronin jälkeläiset saivat arvalla Juudan sukukunnalta, Simeonin sukukunnalta ja Benjaminin sukukunnalta kolmetoista kaupunkia.',
        5: 'Mutta muut kehatilaiset saivat arvalla Efraimin sukukunnan suvuilta, Daanin sukukunnalta ja toiselta puolelta Manassen sukukuntaa kymmenen kaupunkia.',
        6: 'Geersonilaiset saivat arvalla Isaskarin sukukunnan suvuilta, Asserin sukukunnalta ja Naftalin sukukunnalta, sekä toiselta puolelta Manassen sukukuntaa Baasanista, kolmetoista kaupunkia.',
        7: 'Merarilaiset, heidän sukunsa, saivat Ruubenin sukukunnalta, Gaadin sukukunnalta ja Sebulonin sukukunnalta kaksitoista kaupunkia.',
        8: 'Israelilaiset antoivat arvalla leeviläisille nämä kaupungit laidunmaineen, niin kuin Herra oli Mooseksen kautta käskenyt.',
        9: 'Juudan jälkeläisten sukukunnasta ja simeonilaisten sukukunnasta annettiin nämä nimeltä mainitut kaupungit:',
        10: 'Leevin jälkeläisiin, kehatilaisten sukuihin, kuuluville Aaronin jälkeläisille, sillä heille arpa tuli ensin,',
        11: 'annettiin Kirjat-Arba, anakilaisten kantaisän Arban kaupunki, se on Hebron, Juudan vuoristosta, ympärillä olevine laidunmaineen.',
        12: 'Mutta kaupungin peltomaat kylineen annettiin Kaalebille, Jefunnen pojalle, perintömaaksi.',
        13: 'Pappi Aaronin jälkeläisille annettiin tappajan turvakaupunki Hebron laidunmaineen, Libna laidunmaineen,',
        14: 'Jattir laidunmaineen, Estemoa laidunmaineen,',
        15: 'Hoolon laidunmaineen, Debir laidunmaineen,',
        16: 'Ain laidunmaineen, Jutta laidunmaineen ja Beet-Semes laidunmaineen – yhdeksän kaupunkia näistä kahdesta sukukunnasta.',
        17: 'Sitten Benjaminin sukukunnasta Gibeon laidunmaineen, Geba laidunmaineen,',
        18: 'Anatot laidunmaineen ja Almon laidunmaineen – neljä kaupunkia.',
        19: 'Aaronin jälkeläisten, pappien, kaupunkeja oli kaikkiaan kolmetoista kaupunkia laidunmaineen.',
        20: 'Muut leeviläisiin kuuluvat kehatilaisten suvut, muut kehatilaiset, saivat arvalla Efraimin sukukunnalta seuraavat kaupungit:',
        21: 'heille annettiin tappajan turvakaupunki Sikem laidunmaineen Efraimin vuoristosta, Geser laidunmaineen,',
        22: 'Kibsaim laidunmaineen, Beet-Hooron laidunmaineen – neljä kaupunkia;',
        23: 'ja Daanin sukukunnasta Elteke laidunmaineen, Gibbeton laidunmaineen,',
        24: 'Aijalon laidunmaineen ja Gat-Rimmon laidunmaineen – neljä kaupunkia,',
        25: 'ja toisesta puolesta Manassen sukukuntaa Taanak laidunmaineen ja Gat-Rimmon laidunmaineen – kaksi kaupunkia.',
        26: 'Näiden muiden kehatilaisten sukujen kaupunkeja laidunmaineen oli kaikkiaan kymmenen.',
        27: 'Leeviläisten sukuihin kuuluvat geersonilaiset saivat toiselta puolelta Manassen sukukuntaa tappajan turvakaupungin Goolanin laidunmaineen Baasanista ja Beesteran laidunmaineen – kaksi kaupunkia;',
        28: 'ja Isaskarin sukukunnalta Kisjonin laidunmaineen, Daberatin laidunmaineen,',
        29: 'Jarmutin laidunmaineen ja Een-Gannimin laidunmaineen – neljä kaupunkia;',
        30: 'ja Asserin sukukunnalta Misalin laidunmaineen, Abdonin laidunmaineen,',
        31: 'Helkatin laidunmaineen ja Rehobin laidunmaineen – neljä kaupunkia;',
        32: 'ja Naftalin sukukunnalta tappajan turvakaupungin Kedeksen laidunmaineen Galileasta, Hammot-Doorin laidunmaineen ja Kartanin laidunmaineen – kolme kaupunkia.',
        33: 'Geersonilaisten, heidän sukujensa, kaupunkeja oli kaikkiaan kolmetoista kaupunkia laidunmaineen.',
        34: 'Muut leeviläisiin kuuluvat merarilaisten suvut saivat Sebulonin sukukunnalta Jokneamin laidunmaineen, Kartan laidunmaineen,',
        35: 'Dimnan laidunmaineen, Nahalalin laidunmaineen – neljä kaupunkia;',
        36: 'ja Ruubenin sukukunnalta Beserin laidunmaineen, Jahaan laidunmaineen,',
        37: 'Kedemotin laidunmaineen ja Meefaatin laidunmaineen – neljä kaupunkia;',
        38: 'ja Gaadin sukukunnalta tappajan turvakaupungin Raamotin laidunmaineen Gileadista ja Mahanaimin laidunmaineen,',
        39: 'Hesbonin laidunmaineen ja Jaeserin laidunmaineen – yhteensä neljä kaupunkia.',
        40: 'Niitä kaupunkeja, jotka nämä muut leeviläisten sukuihin kuuluvat merarilaiset, heidän sukunsa, saivat arvalla, oli kaikkiaan kaksitoista kaupunkia.',
        41: 'Kaikkiaan oli leeviläisten kaupunkeja israelilaisten perintömaassa neljäkymmentä kahdeksan kaupunkia laidunmaineen.',
        42: 'Näihin kaupunkeihin kuului kuhunkin itse kaupunki ja sen ympärillä olevat laidunmaat. Sellaisia olivat kaikki nämä kaupungit.',
        43: 'Niin Herra antoi Israelille koko sen maan, jonka hän oli vannonut antavansa heidän isilleen. Niin he ottivat sen omakseen ja asettuivat siihen.',
        44: 'Herra soi heidän päästä rauhaan kaikkialla, aivan niin kuin hän valalla vannoen oli luvannut heidän isilleen. Yksikään heidän vihollisistaan ei kestänyt heidän edessään, vaan kaikki heidän vihollisensa Herra antoi heidän käsiinsä.',
        45: 'Ei jäänyt täyttämättä mikään niistä kaikista lupauksista, jotka Herra oli antanut Israelin heimolle, vaan kaikki toteutui.',
    },
    22: {
        1: 'Sitten Joosua kutsui ruubenilaiset, gaadilaiset ja toisen puolen Manassen sukukuntaa',
        2: 'ja sanoi heille: "Te olette noudattaneet kaikkea, mitä Herran palvelija Mooses on käskenyt teidän noudattaa, ja olette kuulleet minua kaikessa, mitä minä olen käskenyt teidän tehdä.',
        3: 'Te ette ole hylänneet veljiänne koko tämän pitkän ajan kuluessa aina tähän päivään asti, ja te olette noudattaneet, mitä Herra, teidän Jumalanne, on käskenyt noudattaa.',
        4: 'Nyt Herra, Jumalanne, on suonut teidän veljienne päästä rauhaan, niin kuin hän heille puhui. Kääntykää siis takaisin ja menkää majoillenne, siihen perintömaahanne, jonka Herran palvelija Mooses antoi teille tuolta puolelta Jordanin.',
        5: 'Noudattakaa vain tarkasti niitä käskyjä ja sitä lakia, jotka Herran palvelija Mooses on teille antanut, rakastakaa Herraa, teidän Jumalaanne, vaeltakaa aina hänen teitään, noudattakaa hänen käskyjään, riippukaa hänessä kiinni ja palvelkaa häntä kaikesta sydämestänne ja kaikesta sielustanne."',
        6: 'Niin Joosua siunasi heidät ja päästi heidät menemään, ja he menivät teltoilleen.',
        7: 'Toiselle puolelle Manassen sukukuntaa Mooses oli antanut maata Baasanista, ja toiselle puolelle Joosua oli antanut maata Jordanin länsipuolelta, heille samoin kuin heidän veljilleen. Kun Joosua päästi heidät menemään teltoilleen ja siunasi heidät,',
        8: 'hän puhui heille sanoen: "Kun te palaatte teltoillenne, mukananne suuret rikkaudet ja suuri määrä karjaa, suuri määrä hopeaa, kultaa, vaskea, rautaa ja vaatteita, jakakaa veljienne kanssa vihollisiltanne saatu saalis."',
        9: 'Niin ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa palasivat takaisin ja lähtivät pois israelilaisten luota Siilosta, joka on Kanaanin maassa, mennäkseen Gileadin maahan, perintömaahansa, johon he olivat asettuneet sen käskyn mukaan, jonka Herra oli Mooseksen kautta antanut.',
        10: 'Kun ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa tulivat Jordanin kivikoille, jotka ovat Kanaanin maan puolella, he rakensivat sinne Jordanille alttarin, valtavan kokoisen alttarin.',
        11: 'Israelilaiset kuulivat sanottavan: "Katso, ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa ovat rakentaneet alttarin, Kanaanin maan suuntaan, Jordanin kivikkojen luo, israelilaisten puolelle."',
        12: 'Kun israelilaiset sen kuulivat, koko israelilaisten seurakunta kokoontui Siiloon lähteäkseen sotaan heitä vastaan.',
        13: 'Israelilaiset lähettivät ruubenilaisten ja gaadilaisten luo ja Manassen sukukunnan toisen puolen luo Gileadin maahan pappi Piinehaan, Eleasarin pojan,',
        14: 'ja hänen kanssaan kymmenen ruhtinasta, yhden ruhtinaan kustakin perhekunnasta, kaikista Israelin sukukunnista. Jokainen heistä oli perhekunnan päämies Israelin heimojen joukossa.',
        15: 'He tulivat ruubenilaisten ja gaadilaisten luo ja Manassen sukukunnan toisen puolen luo Gileadin maahan, puhuivat heille ja sanoivat:',
        16: '"Näin sanoo koko Herran seurakunta: Kuinka te menettelette näin uskottomasti Israelin Jumalaa kohtaan, että nyt käännytte pois Herrasta rakentamalla itsellenne alttarin ja nyt kapinoitte Herraa vastaan?',
        17: 'Eikö meille jo riitä Peorin vuoksi tehty rikos, josta emme ole päässeet puhdistumaan vielä tänäkään päivänä ja josta rangaistus kohtasi Herran seurakuntaa?',
        18: 'Kuitenkin te nytkin käännytte pois Herrasta! Kun te tänä päivänä kapinoitte Herraa vastaan, niin hän huomenna vihastuu koko Israelin seurakuntaan.',
        19: 'Mutta jos teidän perintömaanne on saastainen, niin tulkaa Herran perintömaahan, jossa on Herran asumus, ja asettukaa keskellemme. Älkää kapinoiko Herraa vastaan älkääkä kapinoiko meitä vastaan rakentamalla itsellenne alttaria, toista kuin Herran, Jumalamme, alttari.',
        20: 'Eikö silloin, kun Aakan, Seran poika, oli ollut uskoton ja anastanut itselleen sitä, mikä oli vihitty tuhon omaksi, viha kohdannut koko Israelin seurakuntaa, vaikka hän olikin vain yksi mies? Eikö hänen täytynyt kuolla rikoksensa tähden?"',
        21: 'Silloin ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa vastasivat ja puhuivat Israelin heimojen päämiehille:',
        22: '"Jumala, Jumala, Herra, Jumala, Jumala Herra, hän tietää sen, ja Israel myös tietäköön sen: jos olemme kapinamielessä tai uskottomuudesta Herraa kohtaan – älä meitä silloin tänä päivänä auta –',
        23: 'rakentaneet alttarin kääntyäksemme pois Herrasta, uhrataksemme sen päällä polttouhria ja ruokauhria tai toimittaaksemme sen päällä rauhanuhreja, niin kostakoon Herra itse sen.',
        24: "Totisesti, me olemme tehneet sen vain huolestuneina yhdestä asiasta, siitä, että teidän lapsenne vastaisuudessa voivat sanoa meidän lapsillemme näin: 'Mitä teillä on tekemistä Herran, Israelin Jumalan, kanssa?",
        25: "Onhan Herra pannut Jordanin välirajaksi meille ja teille, te ruubenilaiset ja gaadilaiset. Teillä ei ole mitään osuutta Herraan.' Niin teidän lapsenne voivat saada aikaan, että meidän lapsemme lakkaavat pelkäämästä Herraa.",
        26: 'Sen tähden me sanoimme: Tehkäämme itsellemme alttari, rakentakaamme se, ei polttouhria eikä teurasuhria varten,',
        27: "vaan olemaan meidän ja teidän sekä myös meidän jälkeläistemme välillä meidän jälkeemme todistajana siitä, että tahdomme toimittaa Herran palvelusta hänen edessään, polttouhreja, teurasuhreja ja rauhanuhreja, etteivät teidän lapsenne vastaisuudessa sanoisi meidän lapsillemme: 'Teillä ei ole mitään osuutta Herraan.'",
        28: "Me ajattelimme: Jos he vastaisuudessa sanovat näin meille ja meidän jälkeläisillemme, niin me voimme vastata: 'Katsokaa Herran alttarin kuvaa, jonka esi-isämme ovat tehneet, ei polttouhria eikä teurasuhria varten, vaan olemaan todistajana meidän välillämme ja teidän.'",
        29: 'Pois se, että me kapinoisimme Herraa vastaan ja kääntyisimme tänä päivänä pois Herrasta rakentamalla alttarin polttouhria, ruokauhria ja teurasuhria varten, toisen kuin Herran, Jumalamme, alttarin, joka on hänen asumuksensa edessä!"',
        30: 'Kun pappi Piinehas ja kansan ruhtinaat, Israelin heimojen päämiehet, jotka olivat hänen kanssaan, kuulivat, mitä ruubenilaiset, gaadilaiset ja manasselaiset puhuivat, se oli heille mieleen.',
        31: 'Pappi Piinehas, Eleasarin poika, sanoi ruubenilaisille, gaadilaisille ja manasselaisille: "Nyt me tiedämme, että Herra on keskellämme, koska ette olekaan menetelleet uskottomasti Herraa kohtaan. Näin te pelastitte israelilaiset joutumasta Herran käsiin."',
        32: 'Sen jälkeen pappi Piinehas, Eleasarin poika, ja ruhtinaat palasivat Gileadin maasta, ruubenilaisten ja gaadilaisten luota, takaisin Kanaanin maahan israelilaisten luo ja antoivat heille nämä tiedot.',
        33: 'Ne olivat israelilaisille mieleen, ja israelilaiset ylistivät Jumalaa, eivätkä he enää ajatelleet lähteä sotaan heitä vastaan hävittämään sitä maata, jossa ruubenilaiset ja gaadilaiset asuivat.',
        34: 'Ruubenilaiset ja gaadilaiset kutsuivat alttaria nimellä Ed, sillä se on [todistaja] meidän välillämme siitä, että Herra on Jumala.',
    },
    23: {
        1: 'Pitkän ajan kuluttua, sitten kun Herra oli suonut Israelin päästä rauhaan kaikilta sen ympärillä asuvilta vihollisilta, ja kun Joosua oli käynyt vanhaksi ja iäkkääksi,',
        2: 'Joosua kutsui koolle koko Israelin, sen vanhimmat, päämiehet, tuomarit ja päällysmiehet ja sanoi heille: "Minä olen käynyt vanhaksi ja iäkkääksi.',
        3: 'Te olette itse nähneet kaiken, mitä Herra, Jumalanne, on tehnyt kaikille näille kansoille, jotka hän on karkottanut tieltänne, sillä Herra, teidän Jumalanne, on itse sotinut puolestanne.',
        4: 'Katsokaa, minä olen arponut teille, teidän sukukunnillenne, perintöosaksi nämä kansat, jotka vielä ovat jäljellä, ja kaikki kansat, jotka minä hävitin Jordanista Suureen mereen asti, auringon laskuun päin.',
        5: 'Herra, Jumalanne, työntää itse ne pois edestänne ja karkottaa ne tieltänne, niin että te otatte omaksenne heidän maansa, niin kuin Herra, teidän Jumalanne, on teille puhunut.',
        6: 'Olkaa siis aivan lujat ja noudattakaa tarkasti kaikkea, mitä Mooseksen lain kirjaan on kirjoitettu, poikkeamatta siitä oikealle tai vasemmalle,',
        7: 'niin ettette yhdy näihin teidän keskuuteenne jääneisiin kansoihin, ette mainitse heidän jumaliensa nimiä ettekä vanno niiden nimeen, ette palvele niitä ettekä kumarra niitä,',
        8: 'vaan että riiputte kiinni Herrassa, Jumalassanne, niin kuin olette tehneet aina tähän päivään asti.',
        9: 'Sen tähden Herra on karkottanut teidän tieltänne suuret ja mahtavat kansat, eikä ainoakaan ole kestänyt teidän edessänne aina tähän päivään asti.',
        10: 'Yksi ainoa mies teistä ajoi pakoon tuhat, sillä Herra, Jumalanne, soti itse puolestanne, niin kuin hän on teille puhunut.',
        11: 'Ottakaa siis henkenne tähden tarkka vaari siitä, että rakastatte Herraa, Jumalaanne.',
        12: 'Sillä jos te käännytte hänestä pois ja liitytte näiden keskuuteenne jääneiden kansojen tähteisiin ja lankoudutte heidän kanssaan ja yhdytte heihin ja he teihin,',
        13: 'niin tietäkää, ettei Herra, Jumalanne, enää karkota näitä kansoja tieltänne, vaan ne tulevat teille paulaksi ja ansaksi, kylkienne ruoskaksi ja okaiksi silmiinne, kunnes te häviätte tästä hyvästä maasta, jonka Herra, Jumalanne, on teille antanut.',
        14: 'Katso, minä menen nyt kaiken maailman tietä. Koko sydämenne ja koko sielunne tietäköön, ettei ainoakaan kaikista niistä teitä koskevista lupauksista, jotka Herra, teidän Jumalanne, on antanut, ole jäänyt täyttämättä. Kaikki ovat toteutuneet teille, eikä ainoakaan niistä ole jäänyt täyttämättä.',
        15: 'Niin kuin kaikki teitä koskevat lupaukset, jotka Herra, teidän Jumalanne, on antanut, ovat toteutuneet teille, niin Herra myös antaa kaikkien uhkauksiensa toteutua teille, kunnes hän on hävittänyt teidät tästä hyvästä maasta, jonka Herra, teidän Jumalanne, on teille antanut:',
        16: 'jos te rikotte Herran, Jumalanne, liiton, jonka hän on teille säätänyt, ja menette ja palvelette muita jumalia ja niitä kumarratte, niin Herran viha syttyy teitä kohtaan, ja te häviätte pian siitä hyvästä maasta, jonka hän on teille antanut."',
    },
    24: {
        1: 'Joosua kokosi kaikki Israelin sukukunnat Sikemiin ja kutsui Israelin vanhimmat, sen päämiehet, tuomarit ja päämiehet, ja he asettuivat Jumalan eteen.',
        2: 'Joosua puhui koko kansalle: "Näin sanoo Herra, Israelin Jumala: Tuolla puolella Eufrat-virran asuivat muinoin teidän isänne, myös Terah, Aabrahamin ja Naahorin isä, ja he palvelivat muita jumalia.',
        3: 'Mutta minä otin teidän isänne Aabrahamin tuolta puolelta virran ja kuljetin häntä kautta koko Kanaanin maan ja tein hänen jälkeläisensä lukuisiksi ja annoin hänelle Iisakin.',
        4: 'Iisakille minä annoin Jaakobin ja Eesaun. Eesaulle minä annoin Seirin vuoriston omaksi, mutta Jaakob ja hänen poikansa menivät Egyptiin.',
        5: 'Lähetin Mooseksen ja Aaronin ja rankaisin Egyptiä sillä, mitä siellä tein, ja sen jälkeen vein teidät sieltä pois.',
        6: 'Kun vein isänne pois Egyptistä ja olitte saapuneet meren rannalle, egyptiläiset ajoivat isiänne takaa sotavaunuilla ja ratsumiehillä Kaislamereen saakka.',
        7: 'He huusivat Herraa, ja hän pani pimeyden teidän ja egyptiläisten välille ja antoi meren tulla heidän ylitseen. Se peitti heidät. Omin silmin näitte, mitä tein egyptiläisille. Kun olitte asuneet kauan aikaa erämaassa,',
        8: 'toin teidät amorilaisten maahan, jotka asuivat tuolla puolella Jordanin, ja he taistelivat teitä vastaan. Mutta annoin heidät käsiinne, ja otitte omaksenne heidän maansa, ja tuhosin heidät tieltänne.',
        9: 'Silloin nousi Baalak, Sipporin poika, Mooabin kuningas ja taisteli Israelia vastaan. Hän lähetti kutsumaan Bileamin, Beorin pojan, että hän kiroaisi teidät.',
        10: 'Mutta en tahtonut kuulla Bileamia, vaan hänen täytyi siunata teidät, ja pelastin teidät hänen käsistään.',
        11: 'Kun te olitte menneet Jordanin yli ja tulleet Jerikoon, Jerikon miehet ja amorilaiset, perissiläiset, kanaanilaiset, heettiläiset, girgasilaiset, hivviläiset ja jebusilaiset taistelivat teitä vastaan, mutta annoin heidät teidän käsiinne.',
        12: 'Lähetin herhiläisiä edellänne, ja ne karkottivat heidät tieltänne, ne kaksi amorilaisten kuningasta. Et tehnyt sitä miekallasi ja jousellasi.',
        13: 'Annoin teille maan, josta et ollut vaivaa nähnyt, ja kaupunkeja, joita ette olleet rakentaneet, mutta joihin asetuitte. Te söitte viinitarhoista ja öljypuista, joita ette olleet istuttaneet.',
        14: 'Pelätkää nyt Herraa, palvelkaa häntä nuhteettomasti ja uskollisesti ja poistakaa ne jumalat, joita isänne palvelivat tuolla puolen virran ja Egyptissä, ja palvelkaa Herraa.',
        15: 'Mutta jos pidätte pahana palvella Herraa, niin valitkaa tänä päivänä, ketä tahdotte palvella, niitäkö jumalia, joita teidän isänne palvelivat virran tuolla puolen, vai amorilaisten jumalia, niiden, joiden maassa te asutte. Mutta minä ja minun perheeni, me palvelemme Herraa."',
        16: 'Kansa vastasi ja sanoi: "Pois se, että me hylkäisimme Herran ja palvelisimme muita jumalia!',
        17: 'Sillä Herra on meidän Jumalamme, hän, joka johdatti meidät ja isämme pois Egyptin maasta, orjuuden pesästä, ja joka teki silmiemme edessä suuret tunnusteot ja aina varjeli meitä sillä tiellä, jota vaelsimme, ja kaikkien niiden kansojen keskellä, joiden kautta kuljimme.',
        18: 'Herra karkotti tieltämme kaikki ne kansat, myös amorilaiset, jotka asuivat tässä maassa. Sen tähden me palvelemme Herraa, sillä hän on Jumalamme."',
        19: 'Niin Joosua sanoi kansalle: "Te ette voi palvella Herraa, sillä hän on pyhä Jumala. Hän on kiivas Jumala, hän ei anna anteeksi teidän rikoksianne ja syntejänne.',
        20: 'Jos te hylkäätte Herran ja palvelette vieraita jumalia, niin hän kääntyy pois ja antaa teille käydä pahoin ja tekee teistä lopun, sen sijaan että hän on ennen antanut teille käydä hyvin."',
        21: 'Mutta kansa sanoi Joosualle: "Ei niin, vaan me palvelemme Herraa."',
        22: 'Joosua sanoi kansalle: "Te olette itse todistajina itseänne vastaan, että olette valinneet itsellenne Herran palvellaksenne häntä." He vastasivat: "Olemme."',
        23: 'Hän sanoi: "Poistakaa nyt vieraat jumalat, joita on keskuudessanne, ja taivuttakaa sydämenne Herran, Israelin Jumalan, puoleen."',
        24: 'Kansa vastasi Joosualle: " Herraa, Jumalaamme, me palvelemme, ja hänen ääntään me kuulemme."',
        25: 'Joosua teki sinä päivänä liiton kansan kanssa ja antoi heille Sikemissä käskyt ja oikeudet.',
        26: 'Joosua kirjoitti nämä puheet Jumalan lain kirjaan, ja hän otti suuren kiven ja pystytti sen sinne, tammen alle, joka oli Herran pyhäkössä.',
        27: 'Joosua sanoi kaikelle kansalle: "Katso, tämä kivi on oleva todistajana meitä vastaan, sillä se on kuullut kaikki Herran sanat, jotka hän on meille puhunut, ja se on oleva todistajana teitä vastaan, ettette kieltäisi Jumalaanne."',
        28: 'Sitten Joosua päästi kansan menemään, kunkin perintöosalleen.',
        29: 'Näiden tapausten jälkeen Herran palvelija Joosua, Nuunin poika, kuoli sadan kymmenen vuoden vanhana.',
        30: 'He hautasivat hänet hänen perintöosansa alueelle, Timnat-Serahiin, joka on Efraimin vuoristossa, pohjoispuolelle Gaas-vuorta.',
        31: 'Israel palveli Herraa Joosuan koko elinajan ja niiden vanhinten koko elinajan, jotka elivät vielä kauan Joosuan jälkeen ja tunsivat kaikki ne teot, jotka Herra oli Israelille tehnyt.',
        32: 'Joosefin luut, jotka israelilaiset olivat tuoneet Egyptistä, he hautasivat Sikemiin, sille maapalstalle, jonka Jaakob oli ostanut Hamorin, Sikemin isän, pojilta sadalla kesitalla ja jonka joosefilaiset olivat saaneet perintöosakseen.',
        33: 'Eleasar, Aaronin poika, kuoli, ja he hautasivat hänet Gibeaan, hänen poikansa Piinehaan kaupunkiin, joka oli annettu hänelle Efraimin vuoristosta.',
    },
}
